import numpy as np


def dcap_candidate_seed_sequence(family_seed: int, count: int) -> List[int]:
    """Return the exact structural-candidate stream used by the DCAP generator."""
    if int(count) <= 0:
        raise ValueError('candidate count must be positive.')
    rng = np.random.default_rng(int(family_seed))
    return [int(rng.integers(0, 2**31 - 1)) for _ in range(int(count))]


class _DcapCandidateMasterRngProxy:
    """Override exactly the first scalar candidate draw of the family master RNG."""

    def __init__(self, base_rng: Any, candidate_seed: int, state: Dict[str, Any]):
        self._base_rng = base_rng
        self._candidate_seed = int(candidate_seed)
        self._state = state

    def integers(
        self,
        low: Any,
        high: Any = None,
        size: Any = None,
        dtype: Any = np.int64,
        endpoint: bool = False,
    ) -> Any:
        if not bool(self._state.get('candidate_emitted', False)):
            if size not in (None, (), 1):
                raise RuntimeError(
                    'DCAP candidate override expects stress_search_attempts=1 and '
                    'a scalar master-RNG candidate draw.'
                )
            self._state['candidate_emitted'] = True
            try:
                return np.asarray(self._candidate_seed, dtype=dtype).item()
            except Exception:
                return int(self._candidate_seed)
        return self._base_rng.integers(
            low=low, high=high, size=size, dtype=dtype, endpoint=endpoint
        )

    def __getattr__(self, name: str) -> Any:
        return getattr(self._base_rng, name)


@contextmanager
def dcap_candidate_seed_override_context(
    family_seed: int,
    candidate_seed: Optional[int],
) -> Iterable[Dict[str, Any]]:
    """Temporarily materialize one exact candidate inside a fixed family seed.

    The original generator first creates ``master_rng = default_rng(family_seed)``
    and draws one or more candidate seeds.  This context replaces only the first
    scalar draw of that master RNG.  Every subsequent random-number stream,
    including the candidate RNG and common-pool append RNG, remains unchanged.
    """
    state: Dict[str, Any] = {
        'enabled': candidate_seed is not None,
        'family_seed': int(family_seed),
        'candidate_seed': None if candidate_seed is None else int(candidate_seed),
        'master_rng_wrapped': False,
        'candidate_emitted': False,
    }
    if candidate_seed is None:
        yield state
        return

    original_default_rng = np.random.default_rng

    def patched_default_rng(seed: Any = None) -> Any:
        can_compare = seed is not None
        try:
            seed_value = int(seed) if can_compare else None
        except Exception:
            seed_value = None
        if (
            not bool(state['master_rng_wrapped'])
            and seed_value == int(family_seed)
        ):
            state['master_rng_wrapped'] = True
            return _DcapCandidateMasterRngProxy(
                original_default_rng(seed),
                int(candidate_seed),
                state,
            )
        return original_default_rng(seed)

    np.random.default_rng = patched_default_rng  # type: ignore[assignment]
    try:
        yield state
    finally:
        np.random.default_rng = original_default_rng  # type: ignore[assignment]

    if not bool(state['master_rng_wrapped']) or not bool(state['candidate_emitted']):
        raise RuntimeError(
            'The DCAP candidate override was requested but the family master RNG '
            'candidate draw was not intercepted.  Refusing to run a different instance.'
        )


