def walltime() -> float:
    return time.perf_counter()


class P1DeadlineReached(RuntimeError):
    """Internal control-flow signal used only to stop a strict oracle at a deadline."""


class P1InnerWatchdogNoInterval(RuntimeError):
    """P1 inner watchdog fired before any complete strict RNC lower bound existed."""


def ensure_dir(path: str) -> None:
    os.makedirs(path, exist_ok=True)


def l1_norm(x: np.ndarray) -> float:
    return float(np.sum(np.abs(np.asarray(x, dtype=float))))


def linf_norm(x: np.ndarray) -> float:
    arr = np.asarray(x, dtype=float)
    return float(np.max(np.abs(arr))) if arr.size else 0.0


def format_int_tuple(v: np.ndarray) -> str:
    raw = [int(round(float(x))) for x in np.asarray(v, dtype=float).ravel().tolist()]
    # Convenience display for replicated-Z step-1 variables z=(r1,r2,q1,q2).
    # The actual physical labels are z_phys = r + 15*q.
    if len(raw) == 4 and max(raw[:2] or [0]) <= 14 and min(raw[:2] or [0]) >= 0 and max(raw[2:] or [0]) <= 19 and min(raw[2:] or [0]) >= 0:
        phys = tuple(raw[i] + 15 * raw[i + 2] for i in range(2))
        return f"phys={phys} r={tuple(raw[:2])} q={tuple(raw[2:])}"
    return str(tuple(raw))


def z_signature(v: np.ndarray, decimals: int = 10) -> tuple:
    arr = np.asarray(v, dtype=float).ravel()
    return tuple(float(x) for x in np.round(arr, decimals))


def safe_float(v: Any, default: float = float("nan")) -> float:
    try:
        out = float(v)
    except Exception:
        return float(default)
    return out


def set_gurobi_params(model: "gp.Model", params: Dict[str, Any]) -> None:
    for k, v in params.items():
        try:
            model.setParam(k, v)
        except Exception:
            pass


class TeeRunLogger:
    def __init__(self, path: str, also_stdout: bool = True) -> None:
        ensure_dir(os.path.dirname(path) or ".")
        self._f = open(path, "w", encoding="utf-8")
        self._also_stdout = also_stdout

    def log(self, msg: str = "") -> None:
        if self._also_stdout:
            print(msg, flush=True)
        self._f.write(msg + "\n")
        self._f.flush()

    def close(self) -> None:
        try:
            self._f.close()
        except Exception:
            pass


# ============================================================
# Metrics and logs
# ============================================================

@dataclass
class SolveStats:
    num_lp: int = 0
    num_milp: int = 0
    num_total: int = 0
    solve_time_sec: float = 0.0

    def add(self, runtime: float, is_milp: bool) -> None:
        self.num_total += 1
        if is_milp:
            self.num_milp += 1
        else:
            self.num_lp += 1
        self.solve_time_sec += float(runtime)

    def merge(self, other: "SolveStats") -> None:
        self.num_lp += int(other.num_lp)
        self.num_milp += int(other.num_milp)
        self.num_total += int(other.num_total)
        self.solve_time_sec += float(other.solve_time_sec)


class MetricsLogger:
    def __init__(self, algo_name: str) -> None:
        self.algo = algo_name
        self.rows: List[Dict[str, Any]] = []

    def log(self, **kwargs: Any) -> None:
        self.rows.append(dict(kwargs))

    def to_csv(self, path: str) -> None:
        if not self.rows:
            return
        ensure_dir(os.path.dirname(path) or ".")
        keys = list(self.rows[0].keys())
        with open(path, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=keys)
            writer.writeheader()
            writer.writerows(self.rows)

