# ============================================================
# SMKP instance construction helpers
# ============================================================

def smkp_y_index(knapsack_idx: int, item_idx: int, n_items: int) -> int:
    return int(knapsack_idx) * int(n_items) + int(item_idx)


def reshape_first_stage_y(inst: Instance, z: np.ndarray) -> np.ndarray:
    return np.asarray(z, dtype=float).reshape(inst.m_knapsacks, inst.n_items)


def unpack_scenario_block(inst: Instance, block_vec: np.ndarray) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
    arr = np.asarray(block_vec, dtype=float).ravel()
    d = inst.m_knapsacks * inst.n_items
    keep = arr[:d].reshape(inst.m_knapsacks, inst.n_items)
    delete_slack = arr[d: 2 * d].reshape(inst.m_knapsacks, inst.n_items)
    cap_slack = arr[2 * d: 2 * d + inst.m_knapsacks]
    return keep, delete_slack, cap_slack


def generate_strongly_correlated_items(n_items: int, R: int, rng: np.random.Generator) -> Tuple[np.ndarray, np.ndarray]:
    if n_items <= 0:
        raise ValueError('n_items must be positive.')
    if R <= 0:
        raise ValueError('R must be positive.')
    weights = rng.integers(1, int(R) + 1, size=int(n_items), endpoint=False).astype(int)
    offset = max(1, int(round(float(R) / 10.0)))
    values = (weights + offset).astype(int)
    return weights.astype(float), values.astype(float)


def generate_dissimilar_capacities(weights: np.ndarray, m_knapsacks: int, rng: np.random.Generator) -> np.ndarray:
    weights = np.asarray(weights, dtype=float).ravel()
    total = float(np.sum(weights))
    a_min = float(np.min(weights))
    a_max = float(np.max(weights))
    if m_knapsacks <= 0:
        raise ValueError('m_knapsacks must be positive.')
    if m_knapsacks > weights.size:
        raise ValueError('The paper removes meaningless cases with more knapsacks than items; require m_knapsacks <= n_items.')

    num_sets = int(math.ceil(float(m_knapsacks) / 3.0))
    W = float(total) / float(num_sets)
    caps: List[float] = []
    remaining = int(m_knapsacks)

    while remaining > 0:
        d = min(3, remaining)
        K_lb = (a_max + d * a_min) / W + 0.1
        K_lb = min(K_lb, 0.98)
        if K_lb >= 1.0:
            K_lb = 0.90
        K = float(rng.uniform(K_lb, 1.0))
        partial: List[float] = []
        feasible = True
        for i in range(1, d + 1):
            low = a_max if i == 1 else a_min
            upper = int(math.floor(K * W - sum(partial) - (d - i) * a_min))
            low_i = int(math.ceil(low))
            if upper < low_i:
                feasible = False
                break
            draw = int(rng.integers(low_i, upper + 1))
            partial.append(float(draw))
        if feasible:
            caps.extend(partial)
            remaining -= d
    caps_arr = np.asarray(caps[:m_knapsacks], dtype=float)
    if not (np.max(caps_arr) >= a_max and np.min(caps_arr) >= a_min and np.sum(caps_arr) < total + 1e-9):
        raise RuntimeError('Generated capacities do not satisfy the intended Section 4 properties.')
    return caps_arr


def deduplicate_capacity_events(base_capacity: int, no_change_prob: float, decreased_caps: Sequence[int], decreased_probs: Sequence[float]) -> Tuple[np.ndarray, np.ndarray]:
    prob_by_cap: Dict[int, float] = {int(base_capacity): float(no_change_prob)}
    for cap, prob in zip(decreased_caps, decreased_probs):
        key = int(cap)
        prob_by_cap[key] = prob_by_cap.get(key, 0.0) + float(prob)
    base = int(base_capacity)
    others = sorted([c for c in prob_by_cap.keys() if c != base], reverse=True)
    ordered_caps = [base] + others
    probs = np.asarray([prob_by_cap[c] for c in ordered_caps], dtype=float)
    probs = probs / float(np.sum(probs))
    return np.asarray(ordered_caps, dtype=float), probs


def generate_many_scenarios(
    initial_capacities: np.ndarray,
    rng: np.random.Generator,
    u: float,
    rel_prob_r: float,
    no_change_prob_low: float,
    no_change_prob_high: float,
    decrease_count_low: int,
    decrease_count_high: int,
    target_scenarios_min: int,
    target_scenarios_max: int,
    uncertain_prob_D: float,
    retry_limit: int,
) -> Tuple[np.ndarray, np.ndarray, float, np.ndarray, np.ndarray, List[np.ndarray], List[np.ndarray]]:
    initial_capacities = np.asarray(initial_capacities, dtype=float).ravel()
    m_knapsacks = initial_capacities.size
    if not (0.0 < u <= 1.0):
        raise ValueError('u must satisfy 0 < u <= 1.')
    if rel_prob_r < 1.0:
        raise ValueError('rel_prob_r must be >= 1.')
    if not (0.0 <= uncertain_prob_D <= 1.0):
        raise ValueError('uncertain_prob_D must be in [0,1].')
    if decrease_count_low <= 0 or decrease_count_high < decrease_count_low:
        raise ValueError('invalid decrease-count range.')

    best_payload: Optional[Tuple[np.ndarray, np.ndarray, float, np.ndarray, np.ndarray, List[np.ndarray], List[np.ndarray]]] = None
    best_dist = float('inf')
    target_mid = 0.5 * (float(target_scenarios_min) + float(target_scenarios_max))

    for _ in range(int(retry_limit)):
        uncertain_mask = rng.uniform(0.0, 1.0, size=m_knapsacks) <= float(uncertain_prob_D)
        if not np.any(uncertain_mask):
            uncertain_mask[int(rng.integers(0, m_knapsacks))] = True

        no_change_probs = np.ones(m_knapsacks, dtype=float)
        decrease_counts = np.zeros(m_knapsacks, dtype=int)
        event_caps_list: List[np.ndarray] = []
        event_probs_list: List[np.ndarray] = []

        feasible = True
        for i in range(m_knapsacks):
            base_cap = int(round(float(initial_capacities[i])))
            if not uncertain_mask[i]:
                event_caps_list.append(np.asarray([float(base_cap)], dtype=float))
                event_probs_list.append(np.asarray([1.0], dtype=float))
                no_change_probs[i] = 1.0
                decrease_counts[i] = 0
                continue

            q0 = float(rng.uniform(no_change_prob_low, no_change_prob_high))
            k = int(rng.integers(int(decrease_count_low), int(decrease_count_high) + 1))
            raw_rel = rng.uniform(1.0, float(rel_prob_r), size=k)
            dec_probs = (1.0 - q0) * raw_rel / float(np.sum(raw_rel))
            dec_caps = []
            for _kk in range(k):
                frac = float(rng.uniform(u, 1.0))
                cap = int(math.floor(frac * float(base_cap)))
                cap = max(0, min(cap, base_cap))
                dec_caps.append(cap)
            caps_i, probs_i = deduplicate_capacity_events(base_cap, q0, dec_caps, dec_probs)
            if caps_i.size <= 1:
                feasible = False
                break
            no_change_probs[i] = float(probs_i[0])
            decrease_counts[i] = int(caps_i.size - 1)
            event_caps_list.append(caps_i)
            event_probs_list.append(probs_i)

        if not feasible:
            continue

        scenario_caps: List[np.ndarray] = []
        scenario_probs: List[float] = []
        base_tuple = tuple(int(round(float(x))) for x in initial_capacities.tolist())

        for combo in np.ndindex(tuple(len(v) for v in event_caps_list)):
            caps = tuple(int(round(float(event_caps_list[i][combo[i]]))) for i in range(m_knapsacks))
            prob = 1.0
            for i in range(m_knapsacks):
                prob *= float(event_probs_list[i][combo[i]])
            if caps == base_tuple:
                continue
            scenario_caps.append(np.asarray(caps, dtype=float))
            scenario_probs.append(float(prob))

        P = len(scenario_caps)
        dist = abs(float(P) - target_mid)
        payload = (
            np.vstack(scenario_caps) if scenario_caps else np.zeros((0, m_knapsacks), dtype=float),
            np.asarray(scenario_probs, dtype=float),
            float(np.prod(no_change_probs)),
            no_change_probs.copy(),
            decrease_counts.copy(),
            [arr.copy() for arr in event_caps_list],
            [arr.copy() for arr in event_probs_list],
        )
        if dist < best_dist:
            best_dist = dist
            best_payload = payload
        if target_scenarios_min <= P <= target_scenarios_max:
            return payload

    if best_payload is None:
        raise RuntimeError('Failed to generate a many-scenarios event system; increase retry_limit or relax scenario-count targets.')
    best_P = int(best_payload[0].shape[0])
    if not (int(target_scenarios_min) <= best_P <= int(target_scenarios_max)):
        raise RuntimeError(
            'Failed to hit the requested many-scenarios window. '
            f'Best realized disturbance-scenario count was {best_P}; '
            'change the seed, enlarge the decrease-count range, increase retry_limit, or relax the target window.'
        )
    return best_payload


def build_z_linear_constraints(item_weights: np.ndarray, initial_capacities: np.ndarray, n_items: int, m_knapsacks: int) -> Tuple[np.ndarray, np.ndarray, List[str]]:
    d = int(n_items) * int(m_knapsacks)
    rows: List[np.ndarray] = []
    rhs: List[float] = []
    senses: List[str] = []

    # Initial knapsack capacities: sum_j a_j y_{ij} <= b_i.
    for i in range(m_knapsacks):
        row = np.zeros(d, dtype=float)
        for j in range(n_items):
            row[smkp_y_index(i, j, n_items)] = float(item_weights[j])
        rows.append(row)
        rhs.append(float(initial_capacities[i]))
        senses.append('<=')

    # Every item may be assigned to at most one knapsack.
    for j in range(n_items):
        row = np.zeros(d, dtype=float)
        for i in range(m_knapsacks):
            row[smkp_y_index(i, j, n_items)] = 1.0
        rows.append(row)
        rhs.append(1.0)
        senses.append('<=')

    return np.vstack(rows), np.asarray(rhs, dtype=float), senses


def build_initial_feasible_loading(item_weights: np.ndarray, item_values: np.ndarray, initial_capacities: np.ndarray) -> np.ndarray:
    """Construct a nontrivial first-stage feasible loading y^0 by a fast greedy rule.

    For small nominal assignment spaces, `select_best_initial_feasible_loading`
    strengthens the initial feasible cut by exact enumeration.
    """
    weights = np.asarray(item_weights, dtype=float).ravel()
    values = np.asarray(item_values, dtype=float).ravel()
    capacities = np.asarray(initial_capacities, dtype=float).ravel().copy()
    m_knapsacks = capacities.size
    n_items = weights.size
    y = np.zeros((m_knapsacks, n_items), dtype=float)
    score = values / np.maximum(weights, 1e-12)
    order = sorted(range(n_items), key=lambda j: (-float(score[j]), -float(values[j]), float(weights[j]), int(j)))
    for j in order:
        feasible_i = [i for i in range(m_knapsacks) if capacities[i] + 1e-9 >= weights[j]]
        if not feasible_i:
            continue
        best_i = min(feasible_i, key=lambda i: (capacities[i] - weights[j], -capacities[i], i))
        y[best_i, j] = 1.0
        capacities[best_i] -= weights[j]
    return y.reshape(-1).astype(float)


def feasible_expected_reward_from_z(
    item_weights: np.ndarray,
    item_values: np.ndarray,
    scenario_capacities: np.ndarray,
    scenario_probabilities: np.ndarray,
    p0: float,
    z: np.ndarray,
) -> Tuple[np.ndarray, float]:
    """
    Build the exact remove-only zero-residual recourse for every scenario and
    return both the stacked x-block array and the corresponding expected reward.
    """
    weights = np.asarray(item_weights, dtype=float).ravel()
    values = np.asarray(item_values, dtype=float).ravel()
    scen_caps = np.asarray(scenario_capacities, dtype=float)
    scen_probs = np.asarray(scenario_probabilities, dtype=float).ravel()
    z_arr = np.asarray(z, dtype=float).ravel()
    m_knapsacks = scen_caps.shape[1]
    n_items = weights.size
    y = z_arr.reshape(m_knapsacks, n_items)
    selected_reward = float(np.sum(values * np.sum(y, axis=0)))
    total_reward = float(p0) * selected_reward
    x_rows: List[np.ndarray] = []
    for s in range(scen_caps.shape[0]):
        x_block = build_remove_only_feasible_recourse(weights, z_arr, scen_caps[s])
        x_rows.append(x_block)
        keep = x_block[: m_knapsacks * n_items].reshape(m_knapsacks, n_items)
        total_reward += float(scen_probs[s]) * float(np.sum(values * np.sum(keep, axis=0)))
    return np.vstack(x_rows), float(total_reward)


def select_best_initial_feasible_loading(
    item_weights: np.ndarray,
    item_values: np.ndarray,
    initial_capacities: np.ndarray,
    scenario_capacities: np.ndarray,
    scenario_probabilities: np.ndarray,
    p0: float,
    max_enum_states: int = 200000,
) -> Tuple[np.ndarray, np.ndarray, float]:
    """Pick a nontrivial zero-residual feasible starting point.

    Enumerate nominally feasible assignments in the Table-8 regime (6 items,
    3 knapsacks); use the greedy loading when the state space is too large.
    """
    weights = np.asarray(item_weights, dtype=float).ravel()
    values = np.asarray(item_values, dtype=float).ravel()
    init_caps = np.asarray(initial_capacities, dtype=float).ravel()
    n_items = weights.size
    m_knapsacks = init_caps.size
    total_states = (m_knapsacks + 1) ** n_items

    def eval_z(z_vec: np.ndarray) -> Tuple[np.ndarray, float]:
        x_rows, reward = feasible_expected_reward_from_z(
            item_weights=weights,
            item_values=values,
            scenario_capacities=scenario_capacities,
            scenario_probabilities=scenario_probabilities,
            p0=float(p0),
            z=z_vec,
        )
        return x_rows, -float(reward)

    if total_states > int(max_enum_states):
        z0 = build_initial_feasible_loading(weights, values, init_caps)
        x0, obj0 = eval_z(z0)
        return z0.astype(float), x0.astype(float), float(obj0)

    best_z: Optional[np.ndarray] = None
    best_x: Optional[np.ndarray] = None
    best_obj = float('inf')
    rem = init_caps.astype(float).copy()
    y = np.zeros((m_knapsacks, n_items), dtype=float)

    def dfs(j: int) -> None:
        nonlocal best_z, best_x, best_obj
        if j >= n_items:
            z_vec = y.reshape(-1).astype(float)
            x_rows, obj = eval_z(z_vec)
            if obj < best_obj - 1e-12:
                best_obj = float(obj)
                best_z = z_vec.copy()
                best_x = x_rows.copy()
            return
        # option 1: leave item j unloaded
        dfs(j + 1)
        # option 2: assign item j to one feasible knapsack
        wj = float(weights[j])
        for i in range(m_knapsacks):
            if rem[i] + 1e-9 < wj:
                continue
            y[i, j] = 1.0
            rem[i] -= wj
            dfs(j + 1)
            rem[i] += wj
            y[i, j] = 0.0

    dfs(0)
    if best_z is None or best_x is None:
        z0 = build_initial_feasible_loading(weights, values, init_caps)
        x0, obj0 = eval_z(z0)
        return z0.astype(float), x0.astype(float), float(obj0)
    return best_z.astype(float), best_x.astype(float), float(best_obj)


def build_remove_only_feasible_recourse(inst_like_weights: np.ndarray, z: np.ndarray, scenario_capacities: np.ndarray) -> np.ndarray:
    """
    Given an initial loading z and one scenario capacity vector b^s, construct an
    exact remove-only recourse block with zero residual.
    """
    weights = np.asarray(inst_like_weights, dtype=float).ravel()
    caps = np.asarray(scenario_capacities, dtype=float).ravel()
    m_knapsacks = caps.size
    n_items = weights.size
    y = np.asarray(z, dtype=float).reshape(m_knapsacks, n_items)
    keep = np.zeros_like(y)
    for i in range(m_knapsacks):
        assigned = [j for j in range(n_items) if y[i, j] > 0.5]
        if not assigned:
            continue
        total_w = float(sum(weights[j] for j in assigned))
        kept = set(assigned)
        if total_w > caps[i] + 1e-9:
            removal_order = sorted(assigned, key=lambda j: (weights[j], -j), reverse=True)
            for j in removal_order:
                if total_w <= caps[i] + 1e-9:
                    break
                kept.discard(j)
                total_w -= float(weights[j])
        for j in kept:
            keep[i, j] = 1.0
    delete_slack = y - keep
    cap_slack = caps - np.array([np.dot(weights, keep[i, :]) for i in range(m_knapsacks)], dtype=float)
    if np.any(delete_slack < -1e-9) or np.any(cap_slack < -1e-9):
        raise RuntimeError('Failed to construct remove-only feasible recourse with zero residual.')
    delete_slack = np.maximum(delete_slack, 0.0)
    cap_slack = np.maximum(cap_slack, 0.0)
    return np.concatenate([keep.reshape(-1), delete_slack.reshape(-1), cap_slack], axis=0).astype(float)


def weighted_mean(values: np.ndarray, weights: np.ndarray) -> float:
    vals = np.asarray(values, dtype=float).ravel()
    wts = np.asarray(weights, dtype=float).ravel()
    denom = float(np.sum(wts))
    if vals.size == 0 or wts.size == 0 or denom <= 0.0:
        return 0.0
    return float(np.dot(vals, wts) / denom)



def weighted_std(values: np.ndarray, weights: np.ndarray) -> float:
    vals = np.asarray(values, dtype=float).ravel()
    wts = np.asarray(weights, dtype=float).ravel()
    denom = float(np.sum(wts))
    if vals.size == 0 or wts.size == 0 or denom <= 0.0:
        return 0.0
    mu = weighted_mean(vals, wts)
    var = float(np.dot(wts, (vals - mu) ** 2) / denom)
    return math.sqrt(max(var, 0.0))



def normalized_entropy(probabilities: np.ndarray) -> float:
    probs = np.asarray(probabilities, dtype=float).ravel()
    probs = probs[probs > 1e-15]
    if probs.size <= 1:
        return 0.0
    probs = probs / float(np.sum(probs))
    ent = -float(np.sum(probs * np.log(probs)))
    return float(ent / math.log(float(probs.size))) if probs.size > 1 else 0.0



def pairwise_mean(values: List[float]) -> float:
    if len(values) <= 1:
        return 0.0
    return float(sum(values) / float(len(values)))



def pairwise_hamming(z_list: List[np.ndarray]) -> float:
    if len(z_list) <= 1:
        return 0.0
    vals: List[float] = []
    for i in range(len(z_list)):
        zi = np.asarray(z_list[i], dtype=float).ravel()
        for j in range(i + 1, len(z_list)):
            zj = np.asarray(z_list[j], dtype=float).ravel()
            vals.append(float(np.mean(np.abs(np.round(zi) - np.round(zj)) > 0.5)))
    return pairwise_mean(vals)



def generate_clustered_correlated_items(n_items: int, R: int, rng: np.random.Generator) -> Tuple[np.ndarray, np.ndarray]:
    """
    Stress-oriented variant of the strongly correlated item family.

    The values remain strongly correlated with the weights, but we deliberately create
    a mix of heavy contenders and light filler items so that several nominally feasible
    first-stage loadings become near tied.  This keeps the instance realistic for SMKP
    while making the first-stage face less single-solution-dominant.
    """
    if n_items <= 0:
        raise ValueError('n_items must be positive.')
    if R <= 0:
        raise ValueError('R must be positive.')

    light_count = max(1, min(n_items - 1, int(round(n_items / 3.0))))
    heavy_count = n_items - light_count
    heavy_low = max(2, int(math.floor(0.60 * float(R))))
    heavy_high = max(heavy_low + 1, int(R))
    light_high = max(2, int(math.ceil(0.35 * float(R))))

    heavy = rng.integers(heavy_low, heavy_high + 1, size=heavy_count)
    light = rng.integers(1, light_high + 1, size=light_count)
    weights = np.concatenate([heavy, light]).astype(int)
    rng.shuffle(weights)

    offset = max(1, int(round(float(R) / 10.0)))
    jitter = rng.integers(-2, 3, size=n_items)
    values = np.maximum(1, weights + offset + jitter).astype(int)
    return weights.astype(float), values.astype(float)



def enumerate_nominally_feasible_loadings_raw(
    item_weights: np.ndarray,
    initial_capacities: np.ndarray,
) -> List[np.ndarray]:
    weights = np.asarray(item_weights, dtype=float).ravel()
    capacities = np.asarray(initial_capacities, dtype=float).ravel().copy()
    n_items = int(weights.size)
    m_knapsacks = int(capacities.size)
    y = np.zeros((m_knapsacks, n_items), dtype=float)
    out: List[np.ndarray] = []

    def dfs(j: int) -> None:
        if j >= n_items:
            out.append(y.reshape(-1).astype(float).copy())
            return
        dfs(j + 1)
        wj = float(weights[j])
        for i in range(m_knapsacks):
            if capacities[i] + 1e-9 < wj:
                continue
            y[i, j] = 1.0
            capacities[i] -= wj
            dfs(j + 1)
            capacities[i] += wj
            y[i, j] = 0.0

    dfs(0)
    return out



def analyze_candidate_structure(
    item_weights: np.ndarray,
    item_values: np.ndarray,
    initial_capacities: np.ndarray,
    scenario_capacities: np.ndarray,
    scenario_probabilities: np.ndarray,
    p0: float,
    event_probs_list: List[np.ndarray],
    near_tie_abs_gap: float,
) -> Tuple[Dict[str, float], List[str], List[np.ndarray]]:
    """
    Structural, algorithm-independent benchmark analysis used to pick the
    stabilization-stress family.

    The scoring uses only exact enumeration of feasible first-stage assignments and
    scenario data.  It does *not* run P1 or P2, so the benchmark selection remains fair.
    """
    loadings = enumerate_nominally_feasible_loadings_raw(item_weights=item_weights, initial_capacities=initial_capacities)
    if not loadings:
        raise RuntimeError('No nominally feasible first-stage loadings were found.')

    rows: List[Tuple[float, float, np.ndarray]] = []
    for z in loadings:
        _, reward = feasible_expected_reward_from_z(
            item_weights=item_weights,
            item_values=item_values,
            scenario_capacities=scenario_capacities,
            scenario_probabilities=scenario_probabilities,
            p0=float(p0),
            z=z,
        )
        nominal_reward = float(np.sum(item_values * np.sum(z.reshape(initial_capacities.size, item_weights.size), axis=0)))
        rows.append((float(reward), float(nominal_reward), z.copy()))

    rows.sort(key=lambda x: (-float(x[0]), tuple(int(round(v)) for v in x[2].tolist())))
    best_reward = float(rows[0][0])
    second_reward = float(rows[1][0]) if len(rows) > 1 else float(rows[0][0])
    second_gap = float(best_reward - second_reward)
    near_gap = max(float(near_tie_abs_gap), 0.02 * max(1.0, abs(float(best_reward))))
    near_rows = [row for row in rows if float(row[0]) >= float(best_reward) - float(near_gap)]
    near_tie_count = int(len(near_rows))
    top_rows = rows[: min(6, len(rows))]
    top_zs = [row[2].copy() for row in top_rows]
    top_hamming = pairwise_hamming(top_zs)

    keep_vectors: List[np.ndarray] = []
    deletion_ratios: List[float] = []
    for reward, nominal_reward, z in top_rows:
        x_rows, _ = feasible_expected_reward_from_z(
            item_weights=item_weights,
            item_values=item_values,
            scenario_capacities=scenario_capacities,
            scenario_probabilities=scenario_probabilities,
            p0=float(p0),
            z=z,
        )
        m = int(initial_capacities.size)
        n = int(item_weights.size)
        keep_bits = x_rows[:, : m * n].reshape(-1).astype(float)
        keep_vectors.append(keep_bits)
        if nominal_reward > 1e-12:
            deletion_ratios.append(max(0.0, float(nominal_reward - reward) / float(nominal_reward)))
        else:
            deletion_ratios.append(0.0)
    keep_hamming = pairwise_hamming(keep_vectors)

    event_entropy_vals = [normalized_entropy(np.asarray(probs, dtype=float)) for probs in event_probs_list if len(probs) > 1]
    event_entropy_mean = float(np.mean(event_entropy_vals)) if event_entropy_vals else 0.0

    caps_total = np.sum(np.asarray(scenario_capacities, dtype=float), axis=1)
    probs = np.asarray(scenario_probabilities, dtype=float).ravel()
    cap_mean = weighted_mean(caps_total, probs)
    cap_std = weighted_std(caps_total, probs)
    capacity_total_cv = float(cap_std / max(abs(cap_mean), 1e-12))

    deletion_ratio_best = float(deletion_ratios[0]) if deletion_ratios else 0.0
    deletion_ratio_top_mean = float(np.mean(deletion_ratios)) if deletion_ratios else 0.0
    top_span = float(best_reward - float(top_rows[-1][0])) if top_rows else 0.0

    score = 0.0
    score += 3.0 * min(float(near_tie_count), 8.0) / 8.0
    score += 2.0 * max(0.0, 1.0 - float(second_gap) / max(float(near_gap), 1e-12))
    score += 2.0 * min(1.0, float(top_hamming) / 0.50)
    score += 2.0 * min(1.0, float(keep_hamming) / 0.35)
    score += 1.5 * min(1.0, float(event_entropy_mean) / 0.80)
    score += 1.0 * min(1.0, float(capacity_total_cv) / 0.25)
    score += 1.0 * min(1.0, float(deletion_ratio_best) / 0.20)
    score += 1.0 * min(1.0, float(deletion_ratio_top_mean) / 0.25)

    metrics: Dict[str, float] = {
        'feasible_loading_count': float(len(rows)),
        'best_expected_reward': float(best_reward),
        'second_best_gap': float(second_gap),
        'near_tie_count': float(near_tie_count),
        'near_tie_gap_used': float(near_gap),
        'top6_span': float(top_span),
        'top6_pairwise_hamming': float(top_hamming),
        'top6_keep_hamming': float(keep_hamming),
        'event_entropy_mean': float(event_entropy_mean),
        'scenario_total_capacity_cv': float(capacity_total_cv),
        'best_loading_deletion_ratio': float(deletion_ratio_best),
        'top6_mean_deletion_ratio': float(deletion_ratio_top_mean),
        'stress_score': float(score),
    }

    notes = [
        f"exactly enumerated {len(rows)} nominally feasible first-stage loadings; {near_tie_count} are within {near_gap:.4f} expected-reward units of the best loading",
        f"top-loading diversity is nontrivial: top-6 first-stage Hamming diversity = {top_hamming:.4f}, top-6 scenario keep-pattern diversity = {keep_hamming:.4f}",
        f"scenario event entropy mean = {event_entropy_mean:.4f}, total-capacity CV = {capacity_total_cv:.4f}, best-loading deletion ratio = {deletion_ratio_best:.4f}",
        "the score is computed only from exact structural metrics of the instance family; it never runs P1 or P2 while selecting the benchmark",
    ]
    return metrics, notes, top_zs



def finalize_smkp_instance_from_raw(
    *,
    n_items: int,
    m_knapsacks: int,
    seed: int,
    instance_mode: str,
    item_weights: np.ndarray,
    item_values: np.ndarray,
    initial_capacities: np.ndarray,
    scenario_caps: np.ndarray,
    scenario_probs: np.ndarray,
    p0: float,
    no_change_probs: np.ndarray,
    realized_decrease_counts: np.ndarray,
    event_caps_list: List[np.ndarray],
    event_probs_list: List[np.ndarray],
    generator_notes: List[str],
    generator_metrics: Dict[str, float],
    benchmark_explanation: List[str],
) -> Instance:
    P = int(scenario_caps.shape[0])
    if P <= 0:
        raise RuntimeError('Scenario generator returned zero disturbance scenarios.')
    if not np.isclose(float(p0 + np.sum(scenario_probs)), 1.0, atol=1e-8):
        raise RuntimeError('Scenario probabilities do not sum to one together with p0.')

    d_z = int(m_knapsacks) * int(n_items)
    z_lb = np.zeros(d_z, dtype=float)
    z_ub = np.ones(d_z, dtype=float)
    z_vtypes = ['B'] * d_z
    z_feas, x_feas_seed_blocks, z_feas_obj = select_best_initial_feasible_loading(
        item_weights=item_weights,
        item_values=item_values,
        initial_capacities=initial_capacities,
        scenario_capacities=scenario_caps,
        scenario_probabilities=scenario_probs,
        p0=float(p0),
    )
    z_lin_matrix, z_lin_rhs, z_lin_sense = build_z_linear_constraints(
        item_weights=item_weights,
        initial_capacities=initial_capacities,
        n_items=n_items,
        m_knapsacks=m_knapsacks,
    )

    keep_len = int(m_knapsacks) * int(n_items)
    delete_len = keep_len
    cap_slack_len = int(m_knapsacks)
    n_i = keep_len + delete_len + cap_slack_len
    m_i = keep_len + int(m_knapsacks)

    A_link_keep = np.eye(keep_len, dtype=float)
    A_link_del = np.eye(delete_len, dtype=float)
    A_link_cap = np.zeros((keep_len, cap_slack_len), dtype=float)
    A_top = np.hstack([A_link_keep, A_link_del, A_link_cap])

    A_cap_keep = np.zeros((m_knapsacks, keep_len), dtype=float)
    for i in range(m_knapsacks):
        for j in range(n_items):
            A_cap_keep[i, smkp_y_index(i, j, n_items)] = float(item_weights[j])
    A_cap_del = np.zeros((m_knapsacks, delete_len), dtype=float)
    A_cap_slack = np.eye(m_knapsacks, dtype=float)
    A_bottom = np.hstack([A_cap_keep, A_cap_del, A_cap_slack])
    A_block = np.vstack([A_top, A_bottom])

    B_top = -np.eye(d_z, dtype=float)
    B_bottom = np.zeros((m_knapsacks, d_z), dtype=float)
    B_block = np.vstack([B_top, B_bottom])

    lb_block = np.concatenate([
        np.zeros(keep_len, dtype=float),
        np.zeros(delete_len, dtype=float),
        np.zeros(cap_slack_len, dtype=float),
    ])
    ub_block_template = np.concatenate([
        np.ones(keep_len, dtype=float),
        np.ones(delete_len, dtype=float),
        initial_capacities.astype(float),
    ])
    vtypes_block = ['B'] * keep_len + ['C'] * delete_len + ['C'] * cap_slack_len

    g = np.zeros(d_z, dtype=float)
    for i in range(m_knapsacks):
        for j in range(n_items):
            g[smkp_y_index(i, j, n_items)] = -float(p0) * float(item_values[j])

    blocks: List[Block] = []
    x_feas_rows: List[np.ndarray] = []
    B_full_parts: List[np.ndarray] = []
    b_full_parts: List[np.ndarray] = []

    for s in range(P):
        b_vec = np.concatenate([
            np.zeros(keep_len, dtype=float),
            np.asarray(scenario_caps[s], dtype=float),
        ])
        c_block = np.concatenate([
            np.tile(-float(scenario_probs[s]) * item_values.astype(float), m_knapsacks),
            np.zeros(delete_len + cap_slack_len, dtype=float),
        ])
        ub_block = ub_block_template.copy()
        ub_block[keep_len + delete_len: keep_len + delete_len + cap_slack_len] = np.asarray(scenario_caps[s], dtype=float)
        blk = Block(
            A=A_block.copy(),
            B=B_block.copy(),
            b=b_vec.copy(),
            c=c_block.copy(),
            vtypes=list(vtypes_block),
            lb=lb_block.copy(),
            ub=ub_block.copy(),
        )
        blocks.append(blk)
        x_feas = x_feas_seed_blocks[s].copy()
        x_feas_rows.append(x_feas)
        B_full_parts.append(B_block.copy())
        b_full_parts.append(b_vec.copy())

    label = f"smkp_{instance_mode}_n{n_items}_m{m_knapsacks}_P{P}_seed{seed}"
    notes = list(generator_notes)
    notes.append(f'Initial zero-residual feasible cut is strengthened by exact enumeration over nominally feasible first-stage assignments; selected objective = {float(z_feas_obj):.8f}.')

    return Instance(
        blocks=blocks,
        g=g,
        z_lb=z_lb,
        z_ub=z_ub,
        z_vtypes=z_vtypes,
        z_feas=z_feas,
        x_feas_blocks=np.vstack(x_feas_rows),
        B_full=np.vstack(B_full_parts),
        b_full=np.concatenate(b_full_parts),
        S=P,
        instance_label=label,
        instance_mode=str(instance_mode),
        n_items=int(n_items),
        m_knapsacks=int(m_knapsacks),
        item_weights=item_weights.astype(float),
        item_values=item_values.astype(float),
        initial_capacities=initial_capacities.astype(float),
        scenario_capacities=scenario_caps.astype(float),
        scenario_probabilities=scenario_probs.astype(float),
        p0=float(p0),
        no_change_probabilities=no_change_probs.astype(float),
        decrease_count_per_knapsack=realized_decrease_counts.astype(int),
        per_knapsack_event_capacities=[np.asarray(v, dtype=float) for v in event_caps_list],
        per_knapsack_event_probabilities=[np.asarray(v, dtype=float) for v in event_probs_list],
        z_lin_matrix=np.asarray(z_lin_matrix, dtype=float),
        z_lin_rhs=np.asarray(z_lin_rhs, dtype=float),
        z_lin_sense=list(z_lin_sense),
        generator_notes=list(notes),
        generator_metrics={str(k): float(v) for k, v in generator_metrics.items()},
        generator_score=float(generator_metrics.get('stress_score', float('nan'))),
        benchmark_explanation=list(benchmark_explanation),
    )



def build_smkp_many_scenarios_instance(
    n_items: int = 6,
    m_knapsacks: int = 3,
    seed: int = 1,
    R: int = 30,
    u: float = 0.5,
    rel_prob_r: float = 3.0,
    uncertain_prob_D: float = 1.0,
    no_change_prob_low: float = 0.1,
    no_change_prob_high: float = 0.9,
    decrease_count_low: int = 5,
    decrease_count_high: int = 7,
    target_scenarios_min: int = 202,
    target_scenarios_max: int = 467,
    retry_limit: int = 2000,
    instance_mode: str = 'table8_default',
    stress_search_attempts: int = 24,
    stress_near_tie_abs_gap: float = 1.5,
    ga_num_blocks: int = 18,
    ga_nominal_mass: float = 0.12,
    dcap_num_blocks: int = 18,
    dcap_periods: int = 2,
    dcap_tiers: int = 2,
    dcap_budget_tightness: float = 0.67,
    dcap_gurobi_profile: str = 'balanced',
    dcap_expand_from_blocks: int = 0,
    dcap_expand_jitter: float = 0.03,
    dcap_mildz_target_low: int = 60,
    dcap_mildz_target_high: int = 140,
    dcap_mildz_target_mid: int = 90,
    nested_common_pool_seed_override: Optional[int] = None,
) -> Instance:
    """
    Build a structured benchmark instance in one of several benchmark modes.

    table8_default
        The documented completion of the published many-scenarios SMKP direction.

    stabilization_stress / pessoa_favorable
        A fair, reproducible SMKP family built from the same semantics, but selected by
        *static exact-structure metrics* that make stabilization differences easier to observe.

    ga_like_sun
        A GA-like Sun family: multiple distinct binary-knapsack x-blocks are coupled to
        a mild first-stage assignment block z, and candidates are selected by structural metrics only.

    dcap_like_sun
        A transparent DCAP-like Sun family: a mild first-stage capacity-purchase block z is coupled
        to many distinct local recourse assignment blocks x^p, and candidates are selected by exact
        static structure metrics only.
    """
    if n_items <= 0 or m_knapsacks <= 0:
        raise ValueError('n_items and m_knapsacks must be positive.')
    if m_knapsacks > n_items:
        raise ValueError('Require m_knapsacks <= n_items to avoid meaningless cases, consistent with the paper.')
    if target_scenarios_min <= 0 or target_scenarios_max < target_scenarios_min:
        raise ValueError('Invalid scenario-count target range.')

    mode_raw = str(instance_mode).lower().strip()
    if mode_raw == 'pessoa_favorable':
        mode_raw = 'stabilization_stress'
    if mode_raw == 'ga_like_sun':
        return build_ga_like_sun_instance(
            n_items=int(n_items),
            m_knapsacks=int(m_knapsacks),
            seed=int(seed),
            R=int(R),
            ga_num_blocks=int(ga_num_blocks),
            ga_nominal_mass=float(ga_nominal_mass),
            stress_search_attempts=int(stress_search_attempts),
            stress_near_tie_abs_gap=float(stress_near_tie_abs_gap),
        )
    if mode_raw == 'dcap_like_sun':
        return build_dcap_like_sun_instance(
            n_items=int(n_items),
            m_knapsacks=int(m_knapsacks),
            seed=int(seed),
            R=int(R),
            dcap_num_blocks=int(dcap_num_blocks),
            dcap_periods=int(dcap_periods),
            dcap_tiers=int(dcap_tiers),
            dcap_budget_tightness=float(dcap_budget_tightness),
            dcap_gurobi_profile=str(dcap_gurobi_profile),
            dcap_expand_from_blocks=int(dcap_expand_from_blocks),
            dcap_expand_jitter=float(dcap_expand_jitter),
            dcap_mildz_target_low=int(dcap_mildz_target_low),
            dcap_mildz_target_high=int(dcap_mildz_target_high),
            dcap_mildz_target_mid=int(dcap_mildz_target_mid),
            nested_common_pool_seed_override=nested_common_pool_seed_override,
            stress_search_attempts=int(stress_search_attempts),
            stress_near_tie_abs_gap=float(stress_near_tie_abs_gap),
        )
    if mode_raw not in ('table8_default', 'stabilization_stress'):
        raise ValueError(f'Unsupported instance_mode {instance_mode!r}.')

    def make_candidate(candidate_seed: int, use_clustered_items: bool) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, float, np.ndarray, np.ndarray, List[np.ndarray], List[np.ndarray]]:
        rng = np.random.default_rng(int(candidate_seed))
        if use_clustered_items:
            item_weights, item_values = generate_clustered_correlated_items(n_items=n_items, R=R, rng=rng)
        else:
            item_weights, item_values = generate_strongly_correlated_items(n_items=n_items, R=R, rng=rng)
        initial_capacities = generate_dissimilar_capacities(weights=item_weights, m_knapsacks=m_knapsacks, rng=rng)
        scenario_caps, scenario_probs, p0, no_change_probs, realized_decrease_counts, event_caps_list, event_probs_list = generate_many_scenarios(
            initial_capacities=initial_capacities,
            rng=rng,
            u=float(u),
            rel_prob_r=float(rel_prob_r),
            no_change_prob_low=float(no_change_prob_low),
            no_change_prob_high=float(no_change_prob_high),
            decrease_count_low=int(decrease_count_low),
            decrease_count_high=int(decrease_count_high),
            target_scenarios_min=int(target_scenarios_min),
            target_scenarios_max=int(target_scenarios_max),
            uncertain_prob_D=float(uncertain_prob_D),
            retry_limit=int(retry_limit),
        )
        return (
            item_weights,
            item_values,
            initial_capacities,
            scenario_caps,
            scenario_probs,
            float(p0),
            no_change_probs,
            realized_decrease_counts,
            event_caps_list,
            event_probs_list,
        )

    if mode_raw == 'table8_default':
        item_weights, item_values, initial_capacities, scenario_caps, scenario_probs, p0, no_change_probs, realized_decrease_counts, event_caps_list, event_probs_list = make_candidate(int(seed), use_clustered_items=False)
        generator_notes = [
            'Faithful ingredients from the paper-facing transparent completion: strongly correlated items with R=30; Section 4.2 capacity generation; Section 4.3 event-product logic.',
            'Transparent completion for the Table 8 direction: because max=3 cannot produce about 300 disturbance scenarios with only 3 knapsacks, the code raises the per-knapsack decrease-count range and rejects/resamples until the realized disturbance-scenario count lies in the requested window.',
            'This default mode reproduces the v121.8 default benchmark family; it does not try to bias the generator toward either outer method.',
        ]
        metrics, bench_notes, _ = analyze_candidate_structure(
            item_weights=item_weights,
            item_values=item_values,
            initial_capacities=initial_capacities,
            scenario_capacities=scenario_caps,
            scenario_probabilities=scenario_probs,
            p0=float(p0),
            event_probs_list=event_probs_list,
            near_tie_abs_gap=float(stress_near_tie_abs_gap),
        )
        benchmark_explanation = [
            'table8_default keeps the transparent many-scenarios SMKP completion as the neutral baseline benchmark.',
            *bench_notes,
        ]
        return finalize_smkp_instance_from_raw(
            n_items=n_items,
            m_knapsacks=m_knapsacks,
            seed=seed,
            instance_mode=mode_raw,
            item_weights=item_weights,
            item_values=item_values,
            initial_capacities=initial_capacities,
            scenario_caps=scenario_caps,
            scenario_probs=scenario_probs,
            p0=p0,
            no_change_probs=no_change_probs,
            realized_decrease_counts=realized_decrease_counts,
            event_caps_list=event_caps_list,
            event_probs_list=event_probs_list,
            generator_notes=generator_notes,
            generator_metrics=metrics,
            benchmark_explanation=benchmark_explanation,
        )

    best_payload = None
    best_score = -float('inf')
    best_metrics: Dict[str, float] = {}
    best_notes: List[str] = []
    best_attempt = -1
    master_rng = np.random.default_rng(int(seed))
    attempt_seeds = [int(master_rng.integers(0, 2**31 - 1)) for _ in range(max(1, int(stress_search_attempts)))]
    for attempt_idx, cand_seed in enumerate(attempt_seeds, start=1):
        try:
            cand_rng = np.random.default_rng(int(cand_seed))
            item_weights, item_values = generate_clustered_correlated_items(n_items=n_items, R=R, rng=cand_rng)
            initial_capacities = generate_dissimilar_capacities(weights=item_weights, m_knapsacks=m_knapsacks, rng=cand_rng)
            scenario_caps, scenario_probs, p0, no_change_probs, realized_decrease_counts, event_caps_list, event_probs_list = generate_many_scenarios(
                initial_capacities=initial_capacities,
                rng=cand_rng,
                u=float(u),
                rel_prob_r=float(rel_prob_r),
                no_change_prob_low=float(no_change_prob_low),
                no_change_prob_high=float(no_change_prob_high),
                decrease_count_low=int(decrease_count_low),
                decrease_count_high=int(decrease_count_high),
                target_scenarios_min=int(target_scenarios_min),
                target_scenarios_max=int(target_scenarios_max),
                uncertain_prob_D=float(uncertain_prob_D),
                retry_limit=int(retry_limit),
            )
        except Exception:
            continue

        metrics, notes, _ = analyze_candidate_structure(
            item_weights=item_weights,
            item_values=item_values,
            initial_capacities=initial_capacities,
            scenario_capacities=scenario_caps,
            scenario_probabilities=scenario_probs,
            p0=float(p0),
            event_probs_list=event_probs_list,
            near_tie_abs_gap=float(stress_near_tie_abs_gap),
        )
        score = float(metrics.get('stress_score', -float('inf')))
        if score > best_score:
            best_score = float(score)
            best_attempt = int(attempt_idx)
            best_metrics = dict(metrics)
            best_notes = list(notes)
            best_payload = (
                item_weights.copy(),
                item_values.copy(),
                initial_capacities.copy(),
                scenario_caps.copy(),
                scenario_probs.copy(),
                float(p0),
                no_change_probs.copy(),
                realized_decrease_counts.copy(),
                [arr.copy() for arr in event_caps_list],
                [arr.copy() for arr in event_probs_list],
            )

    if best_payload is None:
        raise RuntimeError('stabilization_stress mode failed to generate a valid candidate instance.')

    item_weights, item_values, initial_capacities, scenario_caps, scenario_probs, p0, no_change_probs, realized_decrease_counts, event_caps_list, event_probs_list = best_payload
    generator_notes = [
        'stabilization_stress keeps the same SMKP semantics and the same 6-items / 3-knapsacks / many-scenarios scale, but uses clustered strongly-correlated items to create heavy contenders and light fillers.',
        'The candidate instance is selected deterministically from a reproducible multi-attempt search using exact structural metrics only: near-tied first-stage loadings, top-loading Hamming diversity, scenario keep/delete diversity, event entropy, and deletion-pressure proxies.',
        f'The search examined {max(1, int(stress_search_attempts))} candidate draws derived from instance_seed={int(seed)} and selected attempt {int(best_attempt)} with structural stress score {best_score:.4f}.',
        'Because the search never runs P1 or P2 during selection, the benchmark remains fair: it targets stabilization-sensitive structure, not one lucky algorithm trace.',
    ]
    benchmark_explanation = [
        'This mode is intentionally less friendly to “one aggressive rho jump solves everything” behavior and more informative about stabilization, history accumulation, and centralization.',
        *best_notes,
    ]
    return finalize_smkp_instance_from_raw(
        n_items=n_items,
        m_knapsacks=m_knapsacks,
        seed=seed,
        instance_mode=mode_raw,
        item_weights=item_weights,
        item_values=item_values,
        initial_capacities=initial_capacities,
        scenario_caps=scenario_caps,
        scenario_probs=scenario_probs,
        p0=p0,
        no_change_probs=no_change_probs,
        realized_decrease_counts=realized_decrease_counts,
        event_caps_list=event_caps_list,
        event_probs_list=event_probs_list,
        generator_notes=generator_notes,
        generator_metrics=best_metrics,
        benchmark_explanation=benchmark_explanation,
    )



def build_ga_like_sun_block(
    n_items: int,
    m_knapsacks: int,
    initial_capacities: np.ndarray,
    local_weights: np.ndarray,
    local_values: np.ndarray,
    local_capacities: np.ndarray,
    block_prob: float,
) -> Block:
    keep_len = int(m_knapsacks) * int(n_items)
    delete_len = keep_len
    cap_slack_len = int(m_knapsacks)
    d_z = keep_len

    A_link_keep = np.eye(keep_len, dtype=float)
    A_link_del = np.eye(delete_len, dtype=float)
    A_link_cap = np.zeros((keep_len, cap_slack_len), dtype=float)
    A_top = np.hstack([A_link_keep, A_link_del, A_link_cap])

    A_cap_keep = np.zeros((m_knapsacks, keep_len), dtype=float)
    for i in range(m_knapsacks):
        for j in range(n_items):
            A_cap_keep[i, smkp_y_index(i, j, n_items)] = float(local_weights[i, j])
    A_cap_del = np.zeros((m_knapsacks, delete_len), dtype=float)
    A_cap_slack = np.eye(m_knapsacks, dtype=float)
    A_bottom = np.hstack([A_cap_keep, A_cap_del, A_cap_slack])
    A_block = np.vstack([A_top, A_bottom])

    B_top = -np.eye(d_z, dtype=float)
    B_bottom = np.zeros((m_knapsacks, d_z), dtype=float)
    B_block = np.vstack([B_top, B_bottom])

    lb_block = np.concatenate([
        np.zeros(keep_len, dtype=float),
        np.zeros(delete_len, dtype=float),
        np.zeros(cap_slack_len, dtype=float),
    ])
    ub_block = np.concatenate([
        np.ones(keep_len, dtype=float),
        np.ones(delete_len, dtype=float),
        np.asarray(local_capacities, dtype=float).ravel(),
    ])
    vtypes_block = ['B'] * keep_len + ['C'] * delete_len + ['C'] * cap_slack_len

    b_vec = np.concatenate([
        np.zeros(keep_len, dtype=float),
        np.asarray(local_capacities, dtype=float).ravel(),
    ])
    c_block = np.concatenate([
        (-float(block_prob) * np.asarray(local_values, dtype=float).reshape(-1)),
        np.zeros(delete_len + cap_slack_len, dtype=float),
    ])
    return Block(
        A=A_block,
        B=B_block,
        b=b_vec,
        c=c_block,
        vtypes=list(vtypes_block),
        lb=lb_block,
        ub=ub_block,
    )



def generate_ga_like_local_data(
    item_weights: np.ndarray,
    item_values: np.ndarray,
    initial_capacities: np.ndarray,
    block_idx: int,
    profile_name: str,
    rng: np.random.Generator,
) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
    weights = np.asarray(item_weights, dtype=float).ravel()
    values = np.asarray(item_values, dtype=float).ravel()
    capacities = np.asarray(initial_capacities, dtype=float).ravel()
    n_items = int(weights.size)
    m_knapsacks = int(capacities.size)
    local_weights = np.zeros((m_knapsacks, n_items), dtype=float)
    local_values = np.zeros((m_knapsacks, n_items), dtype=float)
    local_capacities = np.zeros(m_knapsacks, dtype=float)

    focus_machine = int(block_idx % m_knapsacks)
    value_order = list(np.argsort(-values))
    split = max(1, int(math.ceil(float(n_items) / 2.0)))
    heavy_set = set(int(j) for j in value_order[:split])
    light_set = set(int(j) for j in value_order[split:])

    cap_scales = rng.uniform(0.72, 0.95, size=m_knapsacks)
    if profile_name == 'heavy':
        cap_scales[focus_machine] += 0.06
        cap_scales[(focus_machine + 1) % m_knapsacks] -= 0.03
    elif profile_name == 'light':
        cap_scales[focus_machine] -= 0.02
        cap_scales[(focus_machine + 1) % m_knapsacks] += 0.03
    elif profile_name == 'mixed':
        cap_scales[focus_machine] += 0.02
        cap_scales[(focus_machine + 1) % m_knapsacks] -= 0.04
    else:
        cap_scales += rng.uniform(-0.02, 0.02, size=m_knapsacks)
    cap_scales = np.clip(cap_scales, 0.60, 0.98)

    for i in range(m_knapsacks):
        machine_focus = (i == focus_machine)
        for j in range(n_items):
            w_scale = 1.0 + float(rng.uniform(-0.06, 0.06))
            v_scale = 1.0 + float(rng.uniform(-0.08, 0.08))
            if profile_name == 'heavy':
                if j in heavy_set:
                    w_scale += (-0.10 if machine_focus else 0.03)
                    v_scale += (0.14 if machine_focus else -0.02)
                else:
                    w_scale += (0.04 if machine_focus else 0.00)
                    v_scale += (-0.03 if machine_focus else 0.02)
            elif profile_name == 'light':
                if j in light_set:
                    w_scale += (-0.12 if machine_focus else 0.02)
                    v_scale += (0.12 if machine_focus else -0.01)
                else:
                    w_scale += (0.05 if machine_focus else 0.00)
                    v_scale += (-0.04 if machine_focus else 0.01)
            elif profile_name == 'mixed':
                if ((i + j + int(block_idx)) % 2) == 0:
                    w_scale += -0.08
                    v_scale += 0.10
                else:
                    w_scale += 0.04
                    v_scale += -0.03
                if machine_focus:
                    v_scale += 0.03
            else:
                if machine_focus:
                    w_scale += -0.03
                    v_scale += 0.05

            w_scale = float(np.clip(w_scale, 0.75, 1.25))
            v_scale = float(np.clip(v_scale, 0.75, 1.35))
            local_weights[i, j] = float(max(1, int(round(float(weights[j]) * w_scale))))
            local_values[i, j] = float(max(1, int(round(float(values[j]) * v_scale))))

        local_capacities[i] = float(max(1, int(round(float(capacities[i]) * float(cap_scales[i])))))
    return local_weights.astype(float), local_values.astype(float), local_capacities.astype(float)



def ga_like_local_data_from_block(inst: Instance, blk: Block) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
    m_knapsacks = int(inst.m_knapsacks)
    n_items = int(inst.n_items)
    keep_len = int(m_knapsacks) * int(n_items)
    local_weights = np.zeros((m_knapsacks, n_items), dtype=float)
    for i in range(m_knapsacks):
        row_idx = keep_len + i
        for j in range(n_items):
            local_weights[i, j] = float(blk.A[row_idx, smkp_y_index(i, j, n_items)])
    local_capacities = np.asarray(blk.b[keep_len: keep_len + m_knapsacks], dtype=float).copy()
    payload = getattr(inst, 'family_payload', None) or {}
    block_probs = np.asarray(payload.get('ga_block_probabilities', inst.scenario_probabilities), dtype=float).ravel()
    block_prob = float(block_probs[0]) if block_probs.size else 1.0
    # The exact local values are not required by the feasible repair builder; return a best-effort proxy.
    local_values = np.zeros((m_knapsacks, n_items), dtype=float)
    scale = max(block_prob, 1e-12)
    c_keep = np.asarray(blk.c[:keep_len], dtype=float).reshape(m_knapsacks, n_items)
    local_values[:, :] = -c_keep / scale
    return local_weights, local_values, local_capacities



def analyze_ga_like_candidate_structure(inst: Instance, near_tie_abs_gap: float) -> Tuple[Dict[str, float], List[str], List[np.ndarray]]:
    loadings = enumerate_nominally_feasible_loadings_raw(
        item_weights=inst.item_weights,
        initial_capacities=inst.initial_capacities,
    )
    if not loadings:
        raise RuntimeError('No nominally feasible first-stage loadings were found for ga_like_sun.')

    keep_len = int(inst.m_knapsacks) * int(inst.n_items)
    eval_rows: List[Dict[str, Any]] = []
    for z in loadings:
        bp = feasible_bundle_point_from_z(inst, z, tag='ga_like_eval')
        eval_rows.append({
            'reward': -float(bp.primal_obj),
            'nominal_reward': float(np.sum(inst.item_values * np.sum(bp.z.reshape(inst.m_knapsacks, inst.n_items), axis=0))),
            'z': bp.z.copy(),
            'x_blocks': bp.x_blocks.copy(),
            'keep_bits': bp.x_blocks[:, :keep_len].reshape(-1).astype(float),
        })

    eval_rows.sort(key=lambda row: (-float(row['reward']), tuple(int(round(v)) for v in row['z'].tolist())))
    best_reward = float(eval_rows[0]['reward'])
    second_reward = float(eval_rows[1]['reward']) if len(eval_rows) > 1 else float(eval_rows[0]['reward'])
    second_gap = float(best_reward - second_reward)
    near_gap = max(float(near_tie_abs_gap), 0.02 * max(1.0, abs(float(best_reward))))
    near_rows = [row for row in eval_rows if float(row['reward']) >= float(best_reward) - float(near_gap)]
    near_tie_count = int(len(near_rows))

    top_rows = eval_rows[: min(6, len(eval_rows))]
    top_zs = [np.asarray(row['z'], dtype=float).copy() for row in top_rows]
    top_hamming = pairwise_hamming(top_zs)
    keep_hamming = pairwise_hamming([np.asarray(row['keep_bits'], dtype=float).copy() for row in top_rows])

    payload = getattr(inst, 'family_payload', None) or {}
    block_probs = np.asarray(payload.get('ga_block_probabilities', inst.scenario_probabilities), dtype=float).ravel()
    block_best_patterns: List[np.ndarray] = []
    block_second_gaps: List[float] = []
    block_near_ties = 0
    for p, blk in enumerate(inst.blocks):
        prob_scale = max(float(block_probs[p]) if p < block_probs.size else 1.0, 1e-12)
        local_rows: List[Tuple[float, np.ndarray]] = []
        for row in eval_rows:
            local_obj = float(np.dot(blk.c, row['x_blocks'][p]) / prob_scale)
            local_rows.append((local_obj, np.asarray(row['z'], dtype=float).copy()))
        local_rows.sort(key=lambda t: (float(t[0]), tuple(int(round(v)) for v in t[1].tolist())))
        block_best_patterns.append(local_rows[0][1].copy())
        gap = float(local_rows[1][0] - local_rows[0][0]) if len(local_rows) > 1 else 0.0
        block_second_gaps.append(gap)
        local_near_gap = max(0.25, 0.05 * abs(float(local_rows[0][0])), 0.35 * float(near_tie_abs_gap))
        if gap <= local_near_gap + 1e-12:
            block_near_ties += 1

    block_best_hamming = pairwise_hamming(block_best_patterns)
    pattern_counts: Dict[str, int] = {}
    for z in block_best_patterns:
        sig = format_int_tuple(z)
        pattern_counts[sig] = int(pattern_counts.get(sig, 0)) + 1
    dominant_pattern_share = float(max(pattern_counts.values()) / max(1, len(block_best_patterns))) if pattern_counts else 1.0
    block_pattern_entropy = normalized_entropy(np.asarray([c / max(1, len(block_best_patterns)) for c in pattern_counts.values()], dtype=float)) if pattern_counts else 0.0
    block_near_tie_share = float(block_near_ties / max(1, len(block_best_patterns))) if block_best_patterns else 0.0
    block_second_gap_mean = float(np.mean(block_second_gaps)) if block_second_gaps else 0.0

    score = 0.0
    score += 3.0 * min(float(near_tie_count), 8.0) / 8.0
    score += 2.0 * max(0.0, 1.0 - float(second_gap) / max(float(near_gap), 1e-12))
    score += 1.75 * min(1.0, float(top_hamming) / 0.45)
    score += 1.25 * min(1.0, float(keep_hamming) / 0.35)
    score += 2.0 * float(block_pattern_entropy)
    score += 1.50 * min(1.0, float(block_best_hamming) / 0.45)
    score += 1.50 * max(0.0, 1.0 - float(dominant_pattern_share))
    score += 1.00 * float(block_near_tie_share)

    metrics: Dict[str, float] = {
        'feasible_loading_count': float(len(eval_rows)),
        'best_expected_reward': float(best_reward),
        'second_best_gap': float(second_gap),
        'near_tie_count': float(near_tie_count),
        'near_tie_gap_used': float(near_gap),
        'top6_pairwise_hamming': float(top_hamming),
        'top6_keep_hamming': float(keep_hamming),
        'block_pattern_entropy': float(block_pattern_entropy),
        'dominant_pattern_share': float(dominant_pattern_share),
        'block_best_hamming': float(block_best_hamming),
        'block_near_tie_share': float(block_near_tie_share),
        'block_second_gap_mean': float(block_second_gap_mean),
        'stress_score': float(score),
    }
    notes = [
        f"exactly enumerated {len(eval_rows)} nominally feasible first-stage loadings; {near_tie_count} global patterns are within {near_gap:.4f} expected-reward units of the best loading",
        f"top-loading diversity is nontrivial: top-6 first-stage Hamming diversity = {top_hamming:.4f}, top-6 keep-pattern diversity = {keep_hamming:.4f}",
        f"local block winners are diverse: entropy = {block_pattern_entropy:.4f}, dominant-pattern share = {dominant_pattern_share:.4f}, pairwise Hamming = {block_best_hamming:.4f}",
        f"threshold richness is visible across blocks: local near-tie share = {block_near_tie_share:.4f}, mean local second-gap = {block_second_gap_mean:.4f}",
        "the score is computed only from exact structural metrics of the family; it never runs P1 or P2 while selecting the benchmark",
    ]
    return metrics, notes, top_zs



def build_ga_like_sun_instance(
    n_items: int = 6,
    m_knapsacks: int = 3,
    seed: int = 1,
    R: int = 30,
    ga_num_blocks: int = 18,
    ga_nominal_mass: float = 0.12,
    stress_search_attempts: int = 24,
    stress_near_tie_abs_gap: float = 1.5,
) -> Instance:
    if n_items <= 0 or m_knapsacks <= 0:
        raise ValueError('n_items and m_knapsacks must be positive.')
    if m_knapsacks > n_items:
        raise ValueError('Require m_knapsacks <= n_items to avoid meaningless cases, consistent with the paper.')
    if int(ga_num_blocks) <= 0:
        raise ValueError('ga_num_blocks must be positive.')
    if not (0.0 < float(ga_nominal_mass) < 1.0):
        raise ValueError('ga_nominal_mass must lie in (0,1).')

    best_inst: Optional[Instance] = None
    best_metrics: Dict[str, float] = {}
    best_notes: List[str] = []
    best_attempt = -1
    best_score = -float('inf')

    master_rng = np.random.default_rng(int(seed))
    attempt_seeds = [int(master_rng.integers(0, 2**31 - 1)) for _ in range(max(1, int(stress_search_attempts)))]
    for attempt_idx, cand_seed in enumerate(attempt_seeds, start=1):
        cand_rng = np.random.default_rng(int(cand_seed))
        item_weights, item_values = generate_clustered_correlated_items(n_items=n_items, R=R, rng=cand_rng)
        initial_capacities = generate_dissimilar_capacities(weights=item_weights, m_knapsacks=m_knapsacks, rng=cand_rng)

        p0 = float(ga_nominal_mass)
        raw_probs = cand_rng.uniform(0.75, 1.25, size=int(ga_num_blocks))
        block_probs = (1.0 - float(p0)) * raw_probs / float(np.sum(raw_probs))

        profile_cycle = ['heavy', 'light', 'mixed', 'balanced']
        profiles = [profile_cycle[(k + int(cand_rng.integers(0, len(profile_cycle)))) % len(profile_cycle)] for k in range(int(ga_num_blocks))]
        cand_rng.shuffle(profiles)

        z_lin_matrix, z_lin_rhs, z_lin_sense = build_z_linear_constraints(
            item_weights=item_weights,
            initial_capacities=initial_capacities,
            n_items=n_items,
            m_knapsacks=m_knapsacks,
        )
        d_z = int(m_knapsacks) * int(n_items)
        z_lb = np.zeros(d_z, dtype=float)
        z_ub = np.ones(d_z, dtype=float)
        z_vtypes = ['B'] * d_z
        g = np.zeros(d_z, dtype=float)
        for i in range(m_knapsacks):
            for j in range(n_items):
                g[smkp_y_index(i, j, n_items)] = -float(p0) * float(item_values[j])

        blocks: List[Block] = []
        block_caps_rows: List[np.ndarray] = []
        B_full_parts: List[np.ndarray] = []
        b_full_parts: List[np.ndarray] = []
        for p in range(int(ga_num_blocks)):
            local_weights, local_values, local_caps = generate_ga_like_local_data(
                item_weights=item_weights,
                item_values=item_values,
                initial_capacities=initial_capacities,
                block_idx=p,
                profile_name=str(profiles[p]),
                rng=cand_rng,
            )
            blk = build_ga_like_sun_block(
                n_items=n_items,
                m_knapsacks=m_knapsacks,
                initial_capacities=initial_capacities,
                local_weights=local_weights,
                local_values=local_values,
                local_capacities=local_caps,
                block_prob=float(block_probs[p]),
            )
            blocks.append(blk)
            block_caps_rows.append(np.asarray(local_caps, dtype=float).copy())
            B_full_parts.append(blk.B.copy())
            b_full_parts.append(blk.b.copy())

        z_seed = build_initial_feasible_loading(item_weights, item_values, initial_capacities)
        keep_len = int(m_knapsacks) * int(n_items)
        dummy_x = np.zeros((int(ga_num_blocks), keep_len + keep_len + int(m_knapsacks)), dtype=float)
        inst_candidate = Instance(
            blocks=blocks,
            g=g,
            z_lb=z_lb,
            z_ub=z_ub,
            z_vtypes=z_vtypes,
            z_feas=z_seed.copy(),
            x_feas_blocks=dummy_x.copy(),
            B_full=np.vstack(B_full_parts),
            b_full=np.concatenate(b_full_parts),
            S=int(ga_num_blocks),
            instance_label=f'ga_like_sun_n{int(n_items)}_m{int(m_knapsacks)}_P{int(ga_num_blocks)}_seed{int(seed)}',
            instance_mode='ga_like_sun',
            n_items=int(n_items),
            m_knapsacks=int(m_knapsacks),
            item_weights=np.asarray(item_weights, dtype=float).copy(),
            item_values=np.asarray(item_values, dtype=float).copy(),
            initial_capacities=np.asarray(initial_capacities, dtype=float).copy(),
            scenario_capacities=np.vstack(block_caps_rows).astype(float),
            scenario_probabilities=np.asarray(block_probs, dtype=float).copy(),
            p0=float(p0),
            no_change_probabilities=np.full(int(m_knapsacks), float(p0), dtype=float),
            decrease_count_per_knapsack=np.zeros(int(m_knapsacks), dtype=int),
            per_knapsack_event_capacities=[np.asarray([float(c)], dtype=float) for c in initial_capacities.tolist()],
            per_knapsack_event_probabilities=[np.asarray([1.0], dtype=float) for _ in range(int(m_knapsacks))],
            z_lin_matrix=np.asarray(z_lin_matrix, dtype=float),
            z_lin_rhs=np.asarray(z_lin_rhs, dtype=float),
            z_lin_sense=list(z_lin_sense),
            generator_notes=[],
            generator_metrics={},
            generator_score=float('nan'),
            benchmark_explanation=[],
            family_payload={
                'ga_block_probabilities': [float(v) for v in np.asarray(block_probs, dtype=float).tolist()],
                'ga_block_profiles': [str(v) for v in profiles],
                'report_n_scenarios_means_x_blocks': True,
            },
        )
        inst_candidate.x_feas_blocks = zero_residual_feasible_x_blocks_for_z(inst_candidate, z_seed)
        metrics, notes, _ = analyze_ga_like_candidate_structure(inst_candidate, near_tie_abs_gap=float(stress_near_tie_abs_gap))
        score = float(metrics.get('stress_score', -float('inf')))
        if score > best_score:
            best_score = float(score)
            best_attempt = int(attempt_idx)
            best_metrics = dict(metrics)
            best_notes = list(notes)
            best_inst = inst_candidate

    if best_inst is None:
        raise RuntimeError('ga_like_sun mode failed to generate a valid candidate instance.')

    best_points = enumerate_top_feasible_loadings(best_inst, top_k=1, max_enum_states=200000)
    if best_points:
        best_inst.z_feas = np.asarray(best_points[0].z, dtype=float).copy()
        best_inst.x_feas_blocks = np.asarray(best_points[0].x_blocks, dtype=float).copy()
    else:
        z_seed = build_initial_feasible_loading(best_inst.item_weights, best_inst.item_values, best_inst.initial_capacities)
        best_inst.z_feas = np.asarray(z_seed, dtype=float).copy()
        best_inst.x_feas_blocks = zero_residual_feasible_x_blocks_for_z(best_inst, z_seed)

    best_inst.generator_notes = [
        'ga_like_sun discards the old many-scenarios product-event SMKP family and rebuilds the benchmark around a Sun-style two-block MILP with a mild z-side and many distinct x-blocks.',
        'Each x-block keeps a binary-knapsack flavor: keep/delete variables are linked to the first-stage assignment z, and each block has its own local weight/reward/capacity profile.',
        'The benchmark search is purely structural and deterministic from instance_seed: it exactly enumerates nominally feasible first-stage loadings and scores candidates by near ties, support churn, local-block winner entropy, dominant-pattern share, and threshold richness.',
        f'The search examined {max(1, int(stress_search_attempts))} candidate draws derived from instance_seed={int(seed)} and selected attempt {int(best_attempt)} with structural stress score {float(best_score):.4f}.',
        'The legacy CSV field n_scenarios is kept for backward compatibility with v121.8, but in ga_like_sun it should be interpreted as the number of x-blocks.',
        'z remains mild with only m*n binary assignment variables, which keeps the compare fair to Sun rather than winning by blowing up the z-subproblem artificially.',
    ]
    best_inst.generator_metrics = {str(k): float(v) for k, v in best_metrics.items()}
    best_inst.generator_score = float(best_metrics.get('stress_score', float('nan')))
    best_inst.benchmark_explanation = [
        'ga_like_sun aligns the benchmark with Pessoa’s generalized-assignment geometry: multiple distinct binary-knapsack x-blocks now compete over a common mild assignment block z.',
        'The family is designed to avoid the old tiny-z fast-verify geometry: distinct local blocks pull z toward different near-best assignments, so no single dominant first-stage pattern should win immediately.',
        'The family remains fair to Sun: z is still mild, the same sharp-AL inner engine is used, and instance selection never looks at P1/P2 outcomes.',
        *best_notes,
    ]
    return best_inst



def is_x_block_instance_mode(instance_mode: str) -> bool:
    return str(instance_mode).lower().strip() in ('ga_like_sun', 'dcap_like_sun')



def is_dcap_like_instance_mode(instance_mode: str) -> bool:
    return str(instance_mode).lower().strip() == 'dcap_like_sun'


def apply_dcap_p1_tune_profile(
    args: argparse.Namespace,
    defaults: argparse.Namespace,
    inst: Instance,
    run_logger: Optional[TeeRunLogger] = None,
) -> Tuple[str, List[str]]:
    """Apply the selected dcap_like_sun P1 tuning profile.

    Scale-aware adjustments control the residual gate and inner cut management
    for the local x-block family.
    """
    if not is_dcap_like_instance_mode(inst.instance_mode):
        return 'none', []
    selected_for_tune: List[str] = []
    try:
        selected_for_tune = parse_run_algos_selection(args)
    except Exception:
        selected_for_tune = []
    if selected_for_tune:
        if not any(a in ('p1', 'p1_norho') for a in selected_for_tune):
            return 'none', []
    elif str(args.algo_mode).lower().strip() not in ('p1', 'p1_norho', 'p1_no_rho', 'compare', 'p1_vs_gurobi', 'all_four'):
        return 'none', []

    profile_raw = str(getattr(args, 'dcap_p1_tune_profile', 'auto')).lower().strip()
    if profile_raw == 'none':
        return 'none', []

    profile = profile_raw
    if profile == 'auto':
        profile = 'fast_debug' if int(inst.S) <= 8 else 'balanced'

    changes: List[str] = []

    def _eq(cur: Any, ref: Any) -> bool:
        if isinstance(ref, float):
            return abs(float(cur) - float(ref)) <= 1e-12
        return cur == ref

    def set_if_default(name: str, new_value: Any, formatter: Optional[str] = None) -> None:
        cur = getattr(args, name)
        ref = getattr(defaults, name)
        if not _eq(cur, ref):
            return
        setattr(args, name, new_value)
        if formatter is None:
            changes.append(f'{name}={new_value}')
        else:
            changes.append(f'{name}={format(new_value, formatter)}')

    # Residuals add across local x-blocks; scale the residual gate with the block count.
    feas_gate_scale = 16.0 if profile == 'fast_debug' else 18.0
    dynamic_feas_gate = max(float(getattr(args, 'p1_feas_residual_gate', 25.0)), feas_gate_scale * float(inst.S))
    set_if_default('p1_feas_residual_gate', float(dynamic_feas_gate), '.2f')

    if profile == 'fast_debug':
        set_if_default('rnc_prune_freq', 16)
        set_if_default('rnc_keep_recent', 32)
        set_if_default('p1_warm_start_pool', 5)
        set_if_default('p1_history_keep', 12)
        set_if_default('p1_tail_support_keep', 3)
        set_if_default('p1_directional_beta', 0.10, '.2f')
        set_if_default('p1_feas_rho_boost', 1.10, '.2f')
        set_if_default('p1_tailing_close_rho_boost', 1.30, '.2f')
        set_if_default('p1_tailing_outer_gate', 8.0, '.2f')
    elif profile == 'balanced':
        set_if_default('rnc_prune_freq', 20)
        set_if_default('rnc_keep_recent', 40)
        set_if_default('p1_warm_start_pool', 5)
        set_if_default('p1_history_keep', 10)
        set_if_default('p1_tail_support_keep', 3)
        set_if_default('p1_directional_beta', 0.12, '.2f')
        set_if_default('p1_feas_rho_boost', 1.12, '.2f')
        set_if_default('p1_tailing_close_rho_boost', 1.35, '.2f')
        set_if_default('p1_tailing_outer_gate', 8.0, '.2f')
    else:
        raise ValueError(f'Unsupported dcap_p1_tune_profile {profile_raw!r}.')

    if changes and run_logger is not None:
        run_logger.log(f'dcap_p1_tune_profile = {profile}')
        run_logger.log('applied mild dcap-like P1 tuning: ' + ', '.join(changes))
        run_logger.log('')
    return profile, changes



def dcap_z_index(resource_idx: int, period_idx: int, tier_idx: int, n_periods: int, n_tiers: int) -> int:
    return (int(resource_idx) * int(n_periods) + int(period_idx)) * int(n_tiers) + int(tier_idx)



def dcap_family_payload(inst: Instance) -> Dict[str, Any]:
    payload = getattr(inst, 'family_payload', None) or {}
    return dict(payload)


def dcap_homogeneous_A0_enabled(inst: Instance) -> bool:
    return bool(dcap_family_payload(inst).get('dcap_homogeneous_A0_enabled', False))


def apply_dcap_homogeneous_A0_variant(
    inst: Instance,
    run_logger: Optional[TeeRunLogger] = None,
) -> Instance:
    """Return a new DCAP-like instance with A_p == A_0 for every local block.

    This is an instance transformation, not an oracle shortcut. Every algorithm,
    residual calculation, fixed-z audit, and extensive-form model sees the same
    transformed matrices stored in ``new_inst.blocks``.
    """
    if not is_dcap_like_instance_mode(inst.instance_mode):
        raise ValueError('--dcap_homogeneous_A0_enable is supported only for dcap_like_sun instances.')
    if not inst.blocks:
        raise ValueError('Cannot homogenize an instance with no local blocks.')

    new_inst = copy.deepcopy(inst)
    A0 = np.asarray(new_inst.blocks[0].A, dtype=float).copy()
    shape0 = tuple(int(v) for v in A0.shape)
    changed = 0
    max_abs_diff = 0.0
    fro_sq = 0.0
    for p, blk in enumerate(new_inst.blocks):
        Ap = np.asarray(blk.A, dtype=float)
        if tuple(int(v) for v in Ap.shape) != shape0:
            raise RuntimeError(
                f'HOMOGENEOUS_A0_SHAPE_MISMATCH at block {p}: '
                f'{tuple(Ap.shape)} != {shape0}.'
            )
        diff = Ap - A0
        block_max = float(np.max(np.abs(diff))) if diff.size else 0.0
        max_abs_diff = max(max_abs_diff, block_max)
        fro_sq += float(np.sum(diff * diff))
        if not np.array_equal(Ap, A0):
            changed += 1
        blk.A = A0.copy()

    payload = copy.deepcopy(dcap_family_payload(new_inst))
    # Keep structural metadata consistent with the transformed matrices.  The
    # block objectives/rewards remain scenario-specific, but technology data
    # (task periods and resource requirements) are now copied from block 0.
    original_task_periods = copy.deepcopy(payload.get('dcap_task_periods', []))
    original_requirements = copy.deepcopy(payload.get('dcap_requirements', []))
    if isinstance(original_task_periods, list) and original_task_periods:
        payload['dcap_task_periods'] = [copy.deepcopy(original_task_periods[0]) for _ in range(int(new_inst.S))]
    if isinstance(original_requirements, list) and original_requirements:
        payload['dcap_requirements'] = [copy.deepcopy(original_requirements[0]) for _ in range(int(new_inst.S))]
    payload.update({
        'dcap_homogeneous_A0_enabled': True,
        'dcap_homogeneous_A0_reference_block': 0,
        'dcap_homogeneous_A0_changed_blocks': int(changed),
        'dcap_homogeneous_A0_total_blocks': int(new_inst.S),
        'dcap_homogeneous_A0_original_max_abs_diff': float(max_abs_diff),
        'dcap_homogeneous_A0_original_frobenius_distance': float(math.sqrt(max(0.0, fro_sq))),
        'dcap_homogeneous_A0_definition': 'A_p := A_0 for every local block p; all B_p, b_p, c_p, domains, probabilities, and first-stage data remain unchanged.',
    })
    new_inst.family_payload = payload
    new_inst.instance_label = f'{new_inst.instance_label}_homogeneousA0'
    new_inst.generator_notes = list(new_inst.generator_notes) + [
        'Homogeneous common-technology variant: every local coupling matrix A_p is replaced by A_0 after nested and continuous-tail construction.',
        'All algorithms, residual calculations, fixed-z audits, and the Gurobi extensive form use the same transformed instance.',
    ]
    new_inst.benchmark_explanation = list(new_inst.benchmark_explanation) + [
        'This run is a transparent homogeneous-A0 benchmark, not the original heterogeneous instance.',
    ]
    metrics = dict(new_inst.generator_metrics)
    metrics.update({
        'homogeneous_A0_enabled': 1.0,
        'homogeneous_A0_changed_blocks': float(changed),
        'homogeneous_A0_original_max_abs_diff': float(max_abs_diff),
        'homogeneous_A0_original_frobenius_distance': float(math.sqrt(max(0.0, fro_sq))),
    })
    new_inst.generator_metrics = metrics

    # Rebuild the reference feasible recourse point under the transformed A0 model.
    new_inst.x_feas_blocks = zero_residual_feasible_x_blocks_for_z(new_inst, new_inst.z_feas)
    residual = full_residual(new_inst, new_inst.x_feas_blocks, new_inst.z_feas)
    max_res = float(np.max(np.abs(residual))) if residual.size else 0.0
    if max_res > 1e-8:
        raise RuntimeError(
            f'HOMOGENEOUS_A0_FEASIBLE_POINT_FAILURE: max residual {max_res:.3e}.'
        )

    if run_logger is not None:
        run_logger.log(
            f'[HomogeneousA0] enabled=1 reference_block=0 blocks={int(new_inst.S)} '
            f'changed_blocks={int(changed)} original_max_abs_A_diff={float(max_abs_diff):.6g} '
            f'original_frobenius_distance={float(math.sqrt(max(0.0, fro_sq))):.6g}'
        )
        final_block_hash = _dcap_block_data_prefix_hash(new_inst, int(new_inst.S))
        run_logger.log(
            f'[HomogeneousA0] all algorithms/audits now use A_p=A_0; '
            f'zero_residual_reference_max_abs={max_res:.3e}; final_block_hash={final_block_hash}'
        )
    return new_inst


def instance_objective_constant_offset(inst: Instance) -> float:
    """Return an optional objective constant carried by adapter instances.

    The normal physical extensive-form instances do not use this field.  It is
    used by the P1 effective-r internal adapter for replicated-Z profiles to put
    the analytically fixed q-copy reward on the same objective scale as the
    physical fixed-z EF audits without introducing q as an internal P1 variable.
    """
    try:
        return float(dcap_family_payload(inst).get('p1_objective_constant_offset', 0.0) or 0.0)
    except Exception:
        return 0.0



def dcap_num_periods(inst: Instance) -> int:
    return int(dcap_family_payload(inst).get('dcap_periods', 2))



def dcap_num_tiers(inst: Instance) -> int:
    return int(dcap_family_payload(inst).get('dcap_tiers', 2))



def dcap_tier_capacities_from_inst(inst: Instance) -> np.ndarray:
    payload = dcap_family_payload(inst)
    arr = np.asarray(payload.get('dcap_tier_capacities', []), dtype=float)
    if arr.size == 0:
        raise RuntimeError('dcap_like_sun payload is missing tier capacities.')
    return arr



def dcap_tier_costs_from_inst(inst: Instance) -> np.ndarray:
    payload = dcap_family_payload(inst)
    arr = np.asarray(payload.get('dcap_tier_costs', []), dtype=float)
    if arr.size == 0:
        raise RuntimeError('dcap_like_sun payload is missing tier costs.')
    return arr




def dcap_tail_cont_enabled(inst: Instance) -> bool:
    """Return True when the optional tail-continuous DCAP adapter is active."""
    try:
        return bool(dcap_family_payload(inst).get('dcap_tail_cont_enabled', False))
    except Exception:
        return False


def dcap_tail_cont_dim(inst: Instance) -> int:
    payload = dcap_family_payload(inst)
    d0 = int(payload.get('dcap_tail_orig_dim', payload.get('dcap_effective_z_dim', int(inst.g.size))) or int(inst.g.size))
    if d0 <= 0:
        raise ValueError('tail-continuous DCAP adapter has an invalid original z dimension.')
    return int(d0)


def dcap_tail_delta_from_inst(inst: Instance) -> float:
    return float(dcap_family_payload(inst).get('dcap_tail_delta', 0.0) or 0.0)


def dcap_tail_start_vector(inst: Instance) -> np.ndarray:
    payload = dcap_family_payload(inst)
    d0 = dcap_tail_cont_dim(inst)
    raw = np.asarray(payload.get('dcap_tail_start', []), dtype=float).ravel()
    if raw.size == d0:
        return raw.copy()
    # Fallback is deliberately conservative: use the y-block upper bounds.
    return np.asarray(inst.z_ub[:d0], dtype=float).ravel().copy()



def parse_dcap_tail_active_dims(raw: Any, d0: int) -> List[int]:
    """Parse masked-tail active dimensions.

    Default/all enables all tail dimensions. Passing
    "0", "1", "2", or a comma-separated list keeps the 9D y/b/u layout but
    allows only those u-coordinates to be nonzero.  Indices are zero-based.
    """
    d0 = int(d0)
    if d0 <= 0:
        raise ValueError('tail active dims require positive d0.')
    if raw is None:
        return list(range(d0))
    if isinstance(raw, str):
        s = raw.strip().lower()
        if s in ('', 'all', '*', 'full', 'three', '3'):
            return list(range(d0))
        vals = [int(v.strip()) for v in s.replace(';', ',').split(',') if v.strip()]
    else:
        vals = [int(v) for v in list(raw)]
    out: List[int] = []
    for j in vals:
        if j < 0 or j >= d0:
            raise ValueError(f'tail active dimension {j} is outside 0..{d0-1}.')
        if j not in out:
            out.append(int(j))
    if not out:
        raise ValueError('At least one tail active dimension must be selected, or use all.')
    return out


def dcap_tail_active_dims_from_inst(inst: Instance) -> List[int]:
    payload = dcap_family_payload(inst)
    d0 = dcap_tail_cont_dim(inst)
    return parse_dcap_tail_active_dims(payload.get('dcap_tail_active_dims', 'all'), d0)


def dcap_tail_active_mask_from_inst(inst: Instance) -> np.ndarray:
    d0 = dcap_tail_cont_dim(inst)
    mask = np.zeros(d0, dtype=float)
    for j in dcap_tail_active_dims_from_inst(inst):
        mask[int(j)] = 1.0
    return mask.astype(float)

def dcap_tail_lift_capacity_vector(inst: Instance, zcap_raw: np.ndarray, tol: float = 1e-9) -> np.ndarray:
    """Lift a physical capacity vector zcap into the 9D y/b/u tail layout.

    Masked-tail semantics: the layout remains (y,b,u) for every original
    coordinate, but inactive tail dimensions have u_j fixed to zero.  Their b_j
    variables are intentionally NOT fixed; this preserves the original integer
    upper endpoint y_j=U_j through b_j=1, u_j=0.
    """
    d0 = dcap_tail_cont_dim(inst)
    start = dcap_tail_start_vector(inst)
    active_mask = dcap_tail_active_mask_from_inst(inst)
    delta_vec = max(0.0, dcap_tail_delta_from_inst(inst)) * active_mask
    zcap = np.asarray(zcap_raw, dtype=float).ravel()
    if zcap.size < d0:
        zcap = np.pad(zcap, (0, d0 - zcap.size), mode='constant')
    zcap = zcap[:d0]
    y = np.zeros(d0, dtype=float)
    b = np.zeros(d0, dtype=float)
    u = np.zeros(d0, dtype=float)
    lb_y = np.asarray(inst.z_lb[:d0], dtype=float).ravel() if inst.z_lb.size >= d0 else np.zeros(d0, dtype=float)
    for j in range(d0):
        U = float(start[j])
        val = float(zcap[j])
        dj = float(delta_vec[j])
        if val >= U - tol:
            y[j] = float(round(U))
            b[j] = 1.0
            # If this tail coordinate is inactive, dj=0 and u_j is exactly zero.
            u[j] = min(max(0.0, val - U), dj)
        else:
            upper_disc = max(float(lb_y[j]), U - 1.0)
            y[j] = float(round(min(max(val, float(lb_y[j])), upper_disc)))
            b[j] = 0.0
            u[j] = 0.0
    return np.concatenate([y, b, u]).astype(float)


def dcap_tail_decompose_z(inst: Instance, z: np.ndarray) -> Dict[str, np.ndarray]:
    """Decompose a tail-continuous z vector into y, b, u, and zcap=y+u."""
    d0 = dcap_tail_cont_dim(inst)
    z_arr = np.asarray(z, dtype=float).ravel()
    if z_arr.size == d0:
        z_arr = dcap_tail_lift_capacity_vector(inst, z_arr)
    if z_arr.size < 3 * d0:
        raise ValueError(f'tail-continuous z has size {z_arr.size}, expected at least {3*d0}.')
    y = np.asarray(z_arr[:d0], dtype=float).copy()
    b = np.asarray(z_arr[d0:2 * d0], dtype=float).copy()
    u = np.asarray(z_arr[2 * d0:3 * d0], dtype=float).copy()
    return {'y': y, 'b': b, 'u': u, 'zcap': (y + u).astype(float)}


def dcap_tail_project_z(inst: Instance, z_raw: np.ndarray, tol: float = 1e-9) -> np.ndarray:
    """Project an arbitrary vector onto the mixed discrete-continuous tail domain.

    The projection is intentionally simple and deterministic.  It first maps each
    coordinate into {0,...,U_i-1} U [U_i,U_i+delta], then enforces the existing
    linear side constraints (primarily the DCAP budget) by trimming the small tail
    u first and then decreasing high-cost integer y levels.  This is used only for
    starts, repairs, and fixed-z audits; the actual P1/Gurobi models still optimize
    over the full linear mixed-integer tail formulation.
    """
    if not dcap_tail_cont_enabled(inst):
        return np.asarray(z_raw, dtype=float).ravel().copy()
    d0 = dcap_tail_cont_dim(inst)
    z_arr = np.asarray(z_raw, dtype=float).ravel().copy()
    if z_arr.size >= 3 * d0:
        # Use the capacity represented by the raw y+u coordinates, not b.
        cap_guess = np.asarray(z_arr[:d0], dtype=float) + np.asarray(z_arr[2 * d0:3 * d0], dtype=float)
    else:
        cap_guess = z_arr[:d0]
    cand = dcap_tail_lift_capacity_vector(inst, cap_guess, tol=tol)

    # If the first lift already satisfies the full z-linear system, keep it.
    if z_is_nominal_feasible(inst, cand, tol=tol):
        return cand.astype(float)

    start = dcap_tail_start_vector(inst)
    active_mask = dcap_tail_active_mask_from_inst(inst)
    delta = max(0.0, dcap_tail_delta_from_inst(inst))
    delta_vec = float(delta) * active_mask
    costs = np.asarray(inst.g[:d0], dtype=float).ravel().copy()
    if costs.size != d0:
        costs = np.ones(d0, dtype=float)
    # Larger positive cost coordinates are reduced first because they most directly
    # relax the budget row.  Tie-break by index for deterministic reproducibility.
    order = sorted(range(d0), key=lambda j: (-float(costs[j]), int(j)))
    y = cand[:d0].copy()
    b = cand[d0:2*d0].copy()
    u = cand[2*d0:3*d0].copy()

    guard = 0
    while not z_is_nominal_feasible(inst, np.concatenate([y, b, u]), tol=tol) and guard < 100000:
        changed = False
        # Trim the continuous tail before modifying the integer coordinates.
        for j in order:
            if u[j] > tol:
                u[j] = 0.0
                changed = True
                break
        if not changed:
            for j in order:
                lb_j = float(inst.z_lb[j]) if j < inst.z_lb.size else 0.0
                U = float(start[j])
                if b[j] > 0.5 and y[j] >= U - tol:
                    y[j] = max(lb_j, U - 1.0)
                    b[j] = 0.0
                    u[j] = 0.0
                    changed = True
                    break
                if y[j] > lb_j + tol:
                    y[j] = max(lb_j, y[j] - 1.0)
                    b[j] = 0.0 if y[j] < U - tol else b[j]
                    u[j] = 0.0 if b[j] < 0.5 else min(u[j], float(delta_vec[j]))
                    changed = True
                    break
        if not changed:
            break
        guard += 1

    cand = np.concatenate([y, b, u]).astype(float)
    if z_is_nominal_feasible(inst, cand, tol=tol):
        return cand
    # Final guaranteed fallback: all-zero y/b/u is budget feasible for the DCAP
    # capacity-purchase profiles targeted by this adapter.
    zero = np.zeros(3 * d0, dtype=float)
    if z_is_nominal_feasible(inst, zero, tol=tol):
        return zero
    return np.asarray(inst.z_feas, dtype=float).copy()


def format_tail_cont_z(inst: Instance, z: Optional[np.ndarray]) -> str:
    if z is None:
        return 'tail_cont_enabled=1 returned_y=NA returned_b=NA returned_u=NA returned_zcap=NA max_tail_u=NA'
    dec = dcap_tail_decompose_z(inst, np.asarray(z, dtype=float))
    y = tuple(int(round(float(v))) for v in dec['y'].ravel().tolist())
    b = tuple(int(round(float(v))) for v in dec['b'].ravel().tolist())
    u_vals = tuple(float(v) for v in dec['u'].ravel().tolist())
    zcap_vals = tuple(float(v) for v in dec['zcap'].ravel().tolist())
    u_str = '(' + ', '.join(f'{v:.6g}' for v in u_vals) + ')'
    zcap_str = '(' + ', '.join(f'{v:.6g}' for v in zcap_vals) + ')'
    max_u = float(np.max(np.abs(dec['u']))) if dec['u'].size else 0.0
    start = tuple(float(v) for v in dcap_tail_start_vector(inst).ravel().tolist())
    start_str = '(' + ', '.join(f'{v:.6g}' for v in start) + ')'
    active_dims = tuple(int(v) for v in dcap_tail_active_dims_from_inst(inst))
    return (
        f'tail_cont_enabled=1 tail_active_dims={active_dims} tail_delta={dcap_tail_delta_from_inst(inst):.6g} '
        f'tail_start={start_str} returned_y={y} returned_b={b} '
        f'returned_u={u_str} returned_zcap={zcap_str} max_tail_u={max_u:.6g}'
    )


def append_tail_cont_row_fields(row: Dict[str, Any], inst: Instance, z: Optional[np.ndarray], prefix: str = 'returned') -> None:
    if not dcap_tail_cont_enabled(inst):
        row['tail_cont_enabled'] = 0
        return
    row['tail_cont_enabled'] = 1
    row['tail_delta'] = float(dcap_tail_delta_from_inst(inst))
    row['tail_active_dims'] = str(tuple(int(v) for v in dcap_tail_active_dims_from_inst(inst)))
    row['tail_active_mask'] = str(tuple(int(round(float(v))) for v in dcap_tail_active_mask_from_inst(inst).tolist()))
    row['tail_rnc_weight_scale'] = float(dcap_family_payload(inst).get('dcap_tail_rnc_weight_scale', 0.0) or 0.0)
    row['tail_start'] = str(tuple(float(v) for v in dcap_tail_start_vector(inst).tolist()))
    if z is None:
        row[f'{prefix}_tail_y'] = 'NA'
        row[f'{prefix}_tail_b'] = 'NA'
        row[f'{prefix}_tail_u'] = 'NA'
        row[f'{prefix}_zcap'] = 'NA'
        row[f'{prefix}_max_tail_u'] = float('nan')
        return
    dec = dcap_tail_decompose_z(inst, np.asarray(z, dtype=float))
    row[f'{prefix}_tail_y'] = str(tuple(int(round(float(v))) for v in dec['y'].tolist()))
    row[f'{prefix}_tail_b'] = str(tuple(int(round(float(v))) for v in dec['b'].tolist()))
    row[f'{prefix}_tail_u'] = str(tuple(float(v) for v in dec['u'].tolist()))
    row[f'{prefix}_zcap'] = str(tuple(float(v) for v in dec['zcap'].tolist()))
    row[f'{prefix}_max_tail_u'] = float(np.max(np.abs(dec['u']))) if dec['u'].size else 0.0




