def append_anchor_microexpand_row_fields(row: Dict[str, Any], inst: Instance) -> None:
    """Append scale-specific anchor micro-expansion metadata to summary rows."""
    try:
        payload = dcap_family_payload(inst)
    except Exception:
        payload = {}
    enabled = bool(payload.get('anchor_microexpand_enabled', False))
    row['anchor_microexpand_enabled'] = int(enabled)
    if not enabled:
        return
    int_fields = [
        'anchor_source_blocks',
        'anchor_target_blocks',
        'anchor_appended_blocks',
        'anchor_source_pool_blocks',
        'anchor_source_common_pool_seed',
        'anchor_expand_seed_default',
        'anchor_expand_seed_used',
        'anchor_expand_seed_override_used',
        'anchor_expand_seed_tuned_for_target',
        'anchor_source_first_stage_verified',
        'anchor_source_tail_verified',
        'anchor_source_z_dim',
        'anchor_target_z_dim',
        'anchor_tail_active_dims',
        'anchor_does_not_require_nested_prefix',
    ]
    for key in int_fields:
        val = payload.get(key, -1)
        if isinstance(val, (list, tuple)):
            row[key] = str(tuple(val))
        else:
            row[key] = int(val)
    row['anchor_expand_jitter'] = float(payload.get('anchor_expand_jitter', float('nan')))
    row['anchor_expand_strategy'] = str(payload.get('anchor_expand_strategy', 'NA'))
    row['anchor_tail_active_mask'] = str(tuple(int(round(float(v))) for v in payload.get('anchor_tail_active_mask', [])))
    row['anchor_tail_delta'] = float(payload.get('anchor_tail_delta', float('nan')))
    row['anchor_tail_start'] = str(tuple(float(v) for v in payload.get('anchor_tail_start', [])))
    for key in [
        'anchor_source_hash',
        'anchor_source_first_stage_hash',
        'anchor_source_block_hash',
        'anchor_target_block_hash',
        'anchor_appended_block_hash',
        'anchor_note',
    ]:
        row[key] = str(payload.get(key, 'NA'))


