    lines.append('## Instance diagnostics')
    lines.append('')
    lines.append(f'- instance label: `{inst.instance_label}`')
    lines.append(f'- dcap_gurobi_profile: `{str(getattr(args, "dcap_gurobi_profile", "balanced"))}`')
    lines.append(f'- z dimension: `{int(inst.g.size)}`')
    lines.append(f'- x-blocks: `{int(inst.S)}`')
