    lines.append(f"- reason / diagnosis: {compare_row.get('fail_reason', 'NA')}")
    lines.append('')
    lines.append('## P1 and Gurobi rows')
    lines.append('')
    lines.append(md_table([compare_row], [
        ('instance_seed', 'seed'),
        ('n_scenarios', 'x-blocks'),
        ('P1_certified', 'P1 cert'),
        ('P1_total_time_sec', 'P1 time'),
        ('P1_final_obj', 'P1 obj'),
        ('P1_final_residual', 'P1 residual'),
        ('P1_objective_cert_gap', 'P1 cert gap'),
        ('Gurobi_status', 'Gurobi status'),
        ('Gurobi_runtime', 'Gurobi time'),
        ('Gurobi_incumbent_obj', 'Gurobi obj'),
        ('Gurobi_best_bound', 'Gurobi bound'),
        ('Gurobi_mip_gap', 'Gurobi gap'),
        ('Gurobi_node_count', 'nodes'),
        ('winner', 'winner'),
        ('win_case', 'case'),
    ]))
