def panel_safe_float(value: Any, default: float = float("nan")) -> float:
    try:
        out = float(value)
    except (TypeError, ValueError):
        return float(default)
    return out


def panel_safe_int(value: Any, default: int = 0) -> int:
    try:
        return int(float(value))
    except (TypeError, ValueError, OverflowError):
        return int(default)


def panel_read_csv_first(path: Path) -> Dict[str, str]:
    if not path.is_file():
        raise FileNotFoundError(f"Required CSV not found: {path}")
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        rows = list(csv.DictReader(handle))
    if not rows:
        raise RuntimeError(f"CSV contains no data row: {path}")
    return dict(rows[0])


def panel_read_csv_rows(path: Path) -> List[Dict[str, str]]:
    if not path.is_file():
        raise FileNotFoundError(f"Required CSV not found: {path}")
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        return [dict(row) for row in csv.DictReader(handle)]


def panel_write_csv(path: Path, rows: Sequence[Mapping[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if not rows:
        path.write_text("", encoding="utf-8")
        return
    keys: List[str] = []
    seen = set()
    for row in rows:
        for key in row.keys():
            if key not in seen:
                seen.add(key)
                keys.append(str(key))
    with path.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=keys, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(rows)


def panel_write_json(path: Path, data: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False, allow_nan=True), encoding="utf-8")


def panel_candidate_by_family(family: int) -> PanelCandidate:
    for candidate in PANEL_CANDIDATES:
        if candidate.family_seed == family:
            return candidate
    raise KeyError(f"No declared candidate for family seed {family}")


def panel_parse_family_list(raw: str) -> List[int]:
    cleaned = raw.replace(";", ",").replace(" ", ",")
    values: List[int] = []
    for token in cleaned.split(","):
        token = token.strip()
        if not token:
            continue
        value = int(token)
        if value not in values:
            values.append(value)
    if not values:
        raise ValueError("--families must contain at least one family seed")
    unknown = [value for value in values if value not in {c.family_seed for c in PANEL_CANDIDATES}]
    if unknown:
        raise ValueError(f"Unsupported family seed(s): {unknown}; available: 159,1,2,4")
    return values


def panel_build_child_command(
    *,
    python_exe: str,
    main_script: Path,
    candidate: PanelCandidate,
    algo: str,
    out_dir: Path,
    time_limit: int,
) -> List[str]:
    if algo not in {"p1", "gurobi"}:
        raise ValueError(f"Unsupported algorithm: {algo}")
    return [
        python_exe, "-u", str(main_script),
        "--run_algos", algo,
        "--algo_mode", "p1",
        "--out_dir", str(out_dir),
        "--instance_mode", "dcap_like_sun",
        "--dcap_gurobi_profile", "seed159_sunint_dz3_u6_tail48",
        "--n_items", "10",
        "--n_knapsacks", "3",
        "--dcap_num_blocks", "120",
        "--dcap_periods", "1",
        "--dcap_tiers", "1",
        "--instance_seed", str(candidate.family_seed),
        "--solver_seed", str(candidate.family_seed),
        "--stress_search_attempts", "1",
        "--dcap_candidate_seed_override", str(candidate.candidate_seed),
        "--dcap_candidate_index_label", str(candidate.candidate_index),
        "--dcap_mildz_target_low", "80",
        "--dcap_mildz_target_high", "180",
        "--dcap_mildz_target_mid", "120",
        "--dcap_nested_b60_enable",
        "--dcap_nested_b60_base_blocks", "60",
        "--dcap_nested_b60_step", "60",
        "--dcap_nested_b60_pool_blocks", "360",
        "--dcap_nested_b60_common_pool_seed_override", "161262537",
        "--dcap_nested_b60_jitter", "0.02",
        "--dcap_nested_b60_freeze_first_stage",
        "--dcap_nested_b60_append_strategy", "auto",
        "--dcap_tail_cont_enable",
        "--dcap_tail_active_dims", "1",
        "--dcap_tail_start_mode", "ub",
        "--dcap_tail_delta", "0.10",
        "--dcap_tail_rnc_weight_scale", "0.001",
        "--dcap_homogeneous_A0_enable",
        "--dcap_p1_tune_profile", "auto",
        # Omit --cert_rel_gap_target entirely: the main code uses NaN/omission to disable it.
        "--no-sync_gurobi_mipgap_with_cert_rel_gap",
        # Gurobi stops only if it proves zero MIP gap or reaches TimeLimit.
        "--gurobi_mipgap", "0",
        "--outer_time_limit", str(int(time_limit)),
        "--baseline_time_limit", str(int(time_limit)),
        # The main code requires eps_final > 0. 1e-9 is numerical zero for this experiment.
        # P1 therefore stops only at a practically zero certified absolute gap or the time/iteration limit.
        "--eps_final", "1e-9",
        "--max_outer_iter", "1000",
        "--compare_inner_mode", "fixed",
        "--compare_inner_gap", "0.01",
        "--eps_in", "0.01",
        "--eps_in_min", "0.01",
        "--eps_feas", "1e-6",
        "--eps_sep", "1e-4",
        "--rnc_prune_freq", "20",
        "--threads", "1",
        "--baseline_threads", "1",
        "--block_workers", "4",
        "--block_chunk_multiplier", "1",
        "--p1_final_audit_time_limit", "120",
        "--p1_incumbent_audit_frequency", "5",
        "--p1_incumbent_audit_time_limit", "30",
        "--p1_incumbent_audit_max_per_iter", "1",
        "--p1_verify_time_limit", "300",
    ]


def panel_format_command(command: Sequence[str]) -> str:
    if os.name == "nt":
        return subprocess.list2cmdline(list(command))
    return shlex.join(list(command))


def panel_run_streamed(command: Sequence[str], log_path: Path, cwd: Path) -> int:
    log_path.parent.mkdir(parents=True, exist_ok=True)
    started = time.time()
    with log_path.open("w", encoding="utf-8", errors="replace") as log:
        log.write("COMMAND:\n" + panel_format_command(command) + "\n\n")
        log.flush()
        process = subprocess.Popen(
            list(command),
            cwd=str(cwd),
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            encoding="utf-8",
            errors="replace",
            bufsize=1,
        )
        assert process.stdout is not None
        for line in process.stdout:
            print(line, end="", flush=True)
            log.write(line)
        rc = process.wait()
        elapsed = time.time() - started
        log.write(f"\nRETURN_CODE={rc}\nWRAPPER_ELAPSED_SEC={elapsed:.6f}\n")
    return int(rc)


def panel_summary_exists(candidate_dir: Path, algo: str) -> bool:
    if algo == "p1":
        return (candidate_dir / "p1" / "p1_summary.csv").is_file()
    return (candidate_dir / "gurobi" / "gurobi_summary.csv").is_file()


def panel_extract_hashes(row: Mapping[str, Any]) -> Tuple[str, str]:
    block_hash = str(
        row.get("nested_b60_first_120_blocks_hash")
        or row.get("first_120_blocks_hash")
        or ""
    ).strip()
    stage_hash = str(row.get("nested_b60_first_stage_hash") or "").strip()
    return block_hash, stage_hash


def panel_relative_gap_percent(ub: float, lb: float, tol: float = 1e-6) -> float:
    if not (math.isfinite(ub) and math.isfinite(lb)):
        return float("inf")
    raw = float(ub) - float(lb)
    if raw < -float(tol):
        return float("inf")
    return 100.0 * max(0.0, raw) / max(1.0, abs(float(ub)))


def panel_apply_safe_lb_filter(
    *,
    p1_row: Mapping[str, Any],
    p1_log_rows: Sequence[Mapping[str, Any]],
    gurobi_row: Mapping[str, Any],
    bound_tol: float,
) -> Dict[str, Any]:
    """Audit every P1 lower bound; never repair or replace one after the run."""
    original_lb = panel_safe_float(p1_row.get("global_lb"), float("-inf"))
    p1_ub = panel_safe_float(p1_row.get("global_ub"), float("inf"))
    gurobi_ub = panel_safe_float(
        gurobi_row.get("incumbent_obj", gurobi_row.get("objective_value")),
        float("inf"),
    )
    history: List[Tuple[int, float, float]] = []
    for row in p1_log_rows:
        lb = panel_safe_float(row.get("inner_lb"), float("nan"))
        if math.isfinite(lb):
            history.append((
                panel_safe_int(row.get("t"), 0),
                float(lb),
                panel_safe_float(row.get("wall_time_sec"), float("nan")),
            ))
    rejected = [item for item in history if item[1] > gurobi_ub + float(bound_tol)]
    current_conflict = bool(math.isfinite(original_lb) and original_lb > gurobi_ub + float(bound_tol))
    own_order_conflict = bool(math.isfinite(original_lb) and math.isfinite(p1_ub) and original_lb > p1_ub + float(bound_tol))
    strict_pass = not current_conflict and not own_order_conflict and not rejected
    reason = (
        "STRICT_RNC_LB_AUDIT_PASS" if strict_pass else
        "STRICT_RNC_CURRENT_LB_CONFLICT" if current_conflict else
        "STRICT_RNC_P1_OWN_BOUND_ORDER_CONFLICT" if own_order_conflict else
        "STRICT_RNC_HISTORY_LB_CONFLICT"
    )
    gap_percent = panel_relative_gap_percent(p1_ub, original_lb, tol=float(bound_tol))
    return {
        "filter_name": "P1_POSTRUN_EXTERNAL_FEASIBLE_UB_STRICT_AUDIT_ONLY",
        "external_ub_used_only_for_rejection": 1,
        "p1_gap_uses_p1_own_ub": 1,
        "p1_original_reported_lb": original_lb,
        "p1_own_audited_ub": p1_ub,
        "external_feasible_ub": gurobi_ub,
        "external_feasible_ub_source": "GUROBI_INCUMBENT",
        "p1_history_lb_count": len(history),
        "admissible_p1_history_lb_count": len(history) - len(rejected),
        "rejected_p1_history_lb_count": len(rejected),
        "filter_applied": 0,
        "selected_p1_history_lb": original_lb,
        "selected_p1_history_lb_source_iter": 0,
        "selected_p1_history_lb_source_time_sec": float("nan"),
        "safe_abs_gap": p1_ub - original_lb if math.isfinite(original_lb) else float("inf"),
        "safe_rel_gap_percent": gap_percent,
        "strict_audit_pass": int(strict_pass),
        "reason": reason,
    }


def panel_audit_candidate(candidate: PanelCandidate, candidate_dir: Path, time_limit: int, bound_tol: float) -> Dict[str, Any]:
    p1_dir = candidate_dir / "p1"
    gurobi_dir = candidate_dir / "gurobi"
    p1_row = panel_read_csv_first(p1_dir / "p1_summary.csv")
    gurobi_row = panel_read_csv_first(gurobi_dir / "gurobi_summary.csv")
    p1_log_rows = panel_read_csv_rows(p1_dir / "p1prime_log.csv")

    p1_block_hash, p1_stage_hash = panel_extract_hashes(p1_row)
    g_block_hash, g_stage_hash = panel_extract_hashes(gurobi_row)
    hash_match = (
        p1_block_hash == candidate.first_120_blocks_hash
        and g_block_hash == candidate.first_120_blocks_hash
        and p1_stage_hash == candidate.first_stage_hash
        and g_stage_hash == candidate.first_stage_hash
        and p1_block_hash == g_block_hash
        and p1_stage_hash == g_stage_hash
    )

    safe_audit = panel_apply_safe_lb_filter(
        p1_row=p1_row,
        p1_log_rows=p1_log_rows,
        gurobi_row=gurobi_row,
        bound_tol=bound_tol,
    )
    panel_write_json(p1_dir / "p1_postrun_lb_filter_2000.json", safe_audit)
    panel_write_csv(p1_dir / "p1_postrun_lb_filter_2000.csv", [safe_audit])

    p1_ub = panel_safe_float(safe_audit["p1_own_audited_ub"], float("inf"))
    p1_lb = panel_safe_float(safe_audit["selected_p1_history_lb"], float("-inf"))
    p1_gap_percent = panel_safe_float(safe_audit["safe_rel_gap_percent"], float("inf"))
    gurobi_ub = panel_safe_float(gurobi_row.get("incumbent_obj", gurobi_row.get("objective_value")), float("inf"))
    gurobi_lb = panel_safe_float(gurobi_row.get("best_bound"), float("-inf"))
    gurobi_gap_percent = 100.0 * panel_safe_float(
        gurobi_row.get("mip_gap", gurobi_row.get("cert_rel_gap")), float("inf")
    )
    p1_time = panel_safe_float(p1_row.get("total_time_sec"), float("nan"))
    gurobi_time = panel_safe_float(gurobi_row.get("runtime"), float("nan"))

    p1_zero = math.isfinite(p1_ub) and math.isfinite(p1_lb) and abs(p1_ub - p1_lb) <= bound_tol
    gurobi_zero = (
        math.isfinite(gurobi_ub)
        and math.isfinite(gurobi_lb)
        and abs(gurobi_ub - gurobi_lb) <= bound_tol
    ) or (math.isfinite(gurobi_gap_percent) and gurobi_gap_percent <= 1e-9)

    # P1's total_time_sec includes final audit overhead.  Treat it as having used
    # the full outer budget when it reaches at least time_limit - 10 seconds.
    p1_budget_complete = p1_zero or (math.isfinite(p1_time) and p1_time >= time_limit - 10.0)
    gurobi_budget_complete = gurobi_zero or (math.isfinite(gurobi_time) and gurobi_time >= time_limit - 2.0)

    p1_bound_order_ok = math.isfinite(p1_lb) and math.isfinite(p1_ub) and p1_lb <= p1_ub + bound_tol
    cross_lb_ok = math.isfinite(p1_lb) and math.isfinite(gurobi_ub) and p1_lb <= gurobi_ub + bound_tol
    cross_gbound_ok = math.isfinite(gurobi_lb) and math.isfinite(p1_ub) and gurobi_lb <= p1_ub + bound_tol

    if not math.isfinite(p1_gap_percent) or not math.isfinite(gurobi_gap_percent):
        winner = "INVALID_OR_INCOMPLETE"
    elif abs(p1_gap_percent - gurobi_gap_percent) <= 1e-10:
        winner = "TIE"
    elif p1_gap_percent < gurobi_gap_percent:
        winner = "P1"
    else:
        winner = "GUROBI"

    common_confirmation = bool(
        p1_budget_complete
        and gurobi_budget_complete
        and hash_match
        and p1_bound_order_ok
        and cross_lb_ok
        and cross_gbound_ok
    )
    confirmed_p1 = bool(winner == "P1" and common_confirmation)
    confirmed_gurobi = bool(winner == "GUROBI" and common_confirmation)

    result: Dict[str, Any] = {
        **asdict(candidate),
        "time_limit_sec": time_limit,
        "actual_first_120_blocks_hash": p1_block_hash,
        "actual_first_stage_hash": p1_stage_hash,
        "instance_hash_match": int(hash_match),
        "p1_total_time_sec": p1_time,
        "p1_stop_reason": str(p1_row.get("stop_reason", "")),
        "p1_raw_lb": panel_safe_float(p1_row.get("global_lb"), float("nan")),
        "p1_safe_lb": p1_lb,
        "p1_audited_ub": p1_ub,
        "p1_safe_gap_percent": p1_gap_percent,
        "p1_safe_lb_filter_applied": panel_safe_int(safe_audit.get("filter_applied"), 0),
        "p1_safe_lb_source_iter": panel_safe_int(safe_audit.get("selected_p1_history_lb_source_iter"), 0),
        "p1_safe_lb_source_time_sec": panel_safe_float(safe_audit.get("selected_p1_history_lb_source_time_sec"), float("nan")),
        "p1_history_lb_rejected_count": panel_safe_int(safe_audit.get("rejected_p1_history_lb_count"), 0),
        "p1_exact_zero_gap": int(p1_zero),
        "p1_budget_complete_or_zero": int(p1_budget_complete),
        "gurobi_runtime_sec": gurobi_time,
        "gurobi_status": str(gurobi_row.get("status", "")),
        "gurobi_incumbent": gurobi_ub,
        "gurobi_best_bound": gurobi_lb,
        "gurobi_gap_percent": gurobi_gap_percent,
        "gurobi_exact_zero_gap": int(gurobi_zero),
        "gurobi_budget_complete_or_zero": int(gurobi_budget_complete),
        "p1_bound_order_ok": int(p1_bound_order_ok),
        "p1_lb_vs_gurobi_incumbent_ok": int(cross_lb_ok),
        "gurobi_bound_vs_p1_ub_ok": int(cross_gbound_ok),
        "winner_at_2000s_or_zero": winner,
        "confirmed_p1_win": int(confirmed_p1),
        "confirmed_gurobi_win": int(confirmed_gurobi),
        "comparison_fully_audited": int(common_confirmation),
        "p1_output_dir": str(p1_dir),
        "gurobi_output_dir": str(gurobi_dir),
    }
    panel_write_json(candidate_dir / "comparison_2000.json", result)
    panel_write_csv(candidate_dir / "comparison_2000.csv", [result])
    return result


def panel_main(argv: Optional[Sequence[str]] = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--main-script", type=Path, default=Path(__file__), help="internal child solver path; defaults to this same single file")
    parser.add_argument("--root", type=Path, default=Path(r"D:\sim\4.22.4_final_four_family_B120_2000"))
    parser.add_argument("--time-limit", type=int, default=2000)
    parser.add_argument("--families", type=str, default="159,1,2,4", help="subset of declared family seeds")
    parser.add_argument("--python", dest="python_exe", type=str, default=sys.executable)
    parser.add_argument("--bound-order-tol", type=float, default=1e-5)
    parser.add_argument("--force", action="store_true", help="rerun even when the relevant summary already exists")
    parser.add_argument("--dry-run", action="store_true", help="print all child commands without executing them")
    args = parser.parse_args(argv)

    main_script = args.main_script.expanduser().resolve()
    if not main_script.is_file():
        parser.error(f"Main script not found: {main_script}")
    if args.time_limit <= 0:
        parser.error("--time-limit must be positive")
    try:
        families = panel_parse_family_list(args.families)
    except ValueError as exc:
        parser.error(str(exc))

    root = args.root.expanduser().resolve()
    root.mkdir(parents=True, exist_ok=True)
    panel_write_json(root / "declared_candidates.json", [asdict(panel_candidate_by_family(f)) for f in families])

    print("Fixed candidates:")
    for family in families:
        c = panel_candidate_by_family(family)
        print(f"  family={c.family_seed} candidate={c.candidate_index} candidate_seed={c.candidate_seed}")
    print(f"Output root: {root}")
    print(f"Time limit per algorithm: {args.time_limit} seconds")
    print("Formal policy: P1 relative target omitted/disabled; P1 eps_final=1e-9 (numerical zero); Gurobi MIPGap=0.")

    aggregate: List[Dict[str, Any]] = []
    for family in families:
        candidate = panel_candidate_by_family(family)
        candidate_dir = root / f"family_{candidate.family_seed:04d}_candidate_{candidate.candidate_index:03d}_{candidate.candidate_seed}"
        candidate_dir.mkdir(parents=True, exist_ok=True)
        print("\n" + "=" * 88)
        print(
            f"family={candidate.family_seed} candidate={candidate.candidate_index} "
            f"candidate_seed={candidate.candidate_seed}"
        )

        for algo in ("p1", "gurobi"):
            out_dir = candidate_dir / algo
            command = panel_build_child_command(
                python_exe=args.python_exe,
                main_script=main_script,
                candidate=candidate,
                algo=algo,
                out_dir=out_dir,
                time_limit=args.time_limit,
            )
            panel_write_json(candidate_dir / f"command_{algo}.json", {"command": command})
            (candidate_dir / f"command_{algo}.txt").write_text(panel_format_command(command) + "\n", encoding="utf-8")
            print(f"\n[{algo}] {panel_format_command(command)}")
            if args.dry_run:
                continue
            if panel_summary_exists(candidate_dir, algo) and not args.force:
                print(f"[{algo}] existing summary found; skip. Use --force to rerun.")
                continue
            rc = panel_run_streamed(command, candidate_dir / f"runner_{algo}.log", main_script.parent)
            if rc != 0:
                print(f"[{algo}] child process failed with return code {rc}", file=sys.stderr)
                return rc

        if args.dry_run:
            continue
        try:
            result = panel_audit_candidate(candidate, candidate_dir, args.time_limit, args.bound_order_tol)
        except Exception as exc:
            panel_write_json(candidate_dir / "AUDIT_ERROR.json", {"error": repr(exc)})
            print(f"[audit] failed: {exc}", file=sys.stderr)
            return 2
        aggregate.append(result)
        panel_write_csv(root / "final_four_comparison_2000.csv", aggregate)
        panel_write_json(root / "final_four_comparison_2000.json", aggregate)
        print(
            f"[audit] P1 gap={result['p1_safe_gap_percent']:.6f}% | "
            f"Gurobi gap={result['gurobi_gap_percent']:.6f}% | "
            f"winner={result['winner_at_2000s_or_zero']} | "
            f"confirmed_p1_win={result['confirmed_p1_win']} | confirmed_gurobi_win={result['confirmed_gurobi_win']}"
        )

    if args.dry_run:
        return 0

    confirmed_p1 = sum(panel_safe_int(row.get("confirmed_p1_win"), 0) for row in aggregate)
    confirmed_gurobi = sum(panel_safe_int(row.get("confirmed_gurobi_win"), 0) for row in aggregate)
    final_status = {
        "families_requested": families,
        "families_completed": [panel_safe_int(row.get("family_seed"), 0) for row in aggregate],
        "confirmed_p1_wins": confirmed_p1,
        "confirmed_gurobi_wins": confirmed_gurobi,
        "total_candidates": len(aggregate),
        "time_limit_sec": args.time_limit,
    }
    panel_write_json(root / "FINAL_STATUS.json", final_status)
    (root / "FINAL_STATUS.txt").write_text(
        f"completed={len(aggregate)}/{len(families)}\nconfirmed_p1_wins={confirmed_p1}\nconfirmed_gurobi_wins={confirmed_gurobi}\n",
        encoding="utf-8",
    )
    print("\nCompleted.")
    print(f"Aggregate CSV: {root / 'final_four_comparison_2000.csv'}")
    print(f"Confirmed P1 wins: {confirmed_p1}/{len(aggregate)}")
    print(f"Confirmed Gurobi wins: {confirmed_gurobi}/{len(aggregate)}")
    return 0




def _single_file_dispatch() -> int:
    marker = "--final-panel"
    if marker in sys.argv[1:]:
        panel_argv = [arg for arg in sys.argv[1:] if arg != marker]
        return int(panel_main(panel_argv))
    result = main()
    return 0 if result is None else int(result)



