def _fchain_cfg(family: int) -> Dict[str, Any]:
    key = str(int(family))
    if key not in _FCHAIN_FAMILY_CONFIGS:
        raise KeyError(f"Unsupported family {family}; this panel supports only family 1 or 2.")
    return copy.deepcopy(_FCHAIN_FAMILY_CONFIGS[key])


def _fchain_json_hash(value: Any) -> str:
    return hashlib.sha256(
        json.dumps(_json_safe_for_hash(value), sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    ).hexdigest()


def _fchain_encode_spec(spec: Mapping[str, Any]) -> str:
    raw = json.dumps(_json_safe_for_hash(dict(spec)), sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    return _fchain_base64.urlsafe_b64encode(raw).decode("ascii")


def _fchain_decode_spec(encoded: str) -> Dict[str, Any]:
    try:
        raw = _fchain_base64.urlsafe_b64decode(encoded.encode("ascii"))
        value = json.loads(raw.decode("utf-8"))
    except Exception as exc:
        raise ValueError(f"Invalid family-chain spec: {exc}") from exc
    if not isinstance(value, dict):
        raise ValueError("Family-chain spec must decode to a JSON object.")
    return value


