def _fchain_b120_identity(inst: Instance) -> Dict[str, Any]:
    payload = dcap_family_payload(inst)
    return {
        "block_count": int(inst.S),
        "first_120_blocks_hash": str(payload.get("first_120_blocks_hash", _dcap_block_data_prefix_hash(inst, 120))),
        "first_stage_hash": str(_dcap_first_stage_data_hash(inst)),
        "tail_enabled": int(dcap_tail_cont_enabled(inst)),
        "tail_active_dims": [int(v) for v in dcap_tail_active_dims_from_inst(inst)] if dcap_tail_cont_enabled(inst) else [],
        "tail_active_mask": [int(round(float(v))) for v in dcap_tail_active_mask_from_inst(inst).tolist()] if dcap_tail_cont_enabled(inst) else [],
        "tail_start": [float(v) for v in dcap_tail_start_vector(inst).tolist()] if dcap_tail_cont_enabled(inst) else [],
        "tail_delta": float(dcap_tail_delta_from_inst(inst)) if dcap_tail_cont_enabled(inst) else float("nan"),
    }


def _fchain_build_b120(args: argparse.Namespace, cfg: Mapping[str, Any], run_logger: Optional[TeeRunLogger]) -> Instance:
    inst = _build_fixed_anchor_instance_from_args(args, 120, run_logger=run_logger)
    ident = _fchain_b120_identity(inst)
    if ident["first_120_blocks_hash"] != str(cfg["expected_b120_hash"]):
        raise RuntimeError(
            "FATAL_B120_HASH_MISMATCH: "
            f"family={cfg['family_seed']} expected={cfg['expected_b120_hash']} actual={ident['first_120_blocks_hash']}"
        )
    if ident["first_stage_hash"] != str(cfg["expected_first_stage_hash"]):
        raise RuntimeError(
            "FATAL_FIRST_STAGE_HASH_MISMATCH: "
            f"family={cfg['family_seed']} expected={cfg['expected_first_stage_hash']} actual={ident['first_stage_hash']}"
        )
    if not (
        ident["tail_enabled"] == 1
        and ident["tail_active_dims"] == [1]
        and ident["tail_active_mask"] == [0, 1, 0]
        and [int(round(v)) for v in ident["tail_start"]] == [6, 6, 6]
        and abs(float(ident["tail_delta"]) - 0.10) <= 1e-12
    ):
        raise RuntimeError(f"FATAL_B120_TAIL_MISMATCH: {ident}")
    return inst


